const CONVS={1:CONV,2:[{"n":1,"t":["九月去北京旅游最好。","Jiǔyuè qù běijīng lǚyóu zuìhǎo.","Nếu đi Bắc Kinh để du lịch thì tốt nhất là đi vào tháng chín."],"s":[{"p":["在学校","Ở trường"],"l":[["A","我要去北京旅游，你觉得什么时候去最好？","Wǒyào qù běijīng lǚyóu, nǐ juéde shénme shíhòu qù zuìhǎo?","Mình sẽ đi Bắc Kinh để du lịch, theo bạn thì đi vào lúc nào là tốt nhất?"],["B","九月去北京旅游最好。","Jiǔyuè qù běijīng lǚyóu zuìhǎo.","Nếu đi Bắc Kinh để du lịch thì tốt nhất là đi vào tháng chín."],["A","为什么？","Wèishénme?","Tại sao vậy?"],["B","九月的北京天气不冷也不热。","Jiǔyuè de běijīng tiānqì bùlěng yě bù rè.","Vì vào tháng chín, thời tiết ở Bắc Kinh không lạnh cũng không nóng."]]},{"p":["看照片","Xem ảnh"],"l":[["A","你喜欢什么运动？","Nǐ xǐhuān shénme yùndòng?","Bạn thích môn thể thao nào?"],["B","我最喜欢踢足球。","Wǒ zuì xǐhuān tīzúqiú.","Mình thích đá bóng nhất."],["A","下午我们一起去踢足球吧。","Xiàwǔ wǒmen yìqǐ qù tīzúqiú ba.","Vậy buổi chiều chúng ta cùng đi đá bóng nhé."],["B","好啊！","Hǎo a!","Được đấy!"]]},{"p":["在家里","Ở nhà"],"l":[["A","我们要不要买几个新的椅子？","Wǒmen yào búyào mǎi jǐgè xīn de yǐzi?","Chúng ta có cần mua mấy chiếc ghế dựa mới không?"],["B","好啊。什么时候去买？","Hǎo a. shénme shíhòu qù mǎi?","Được thôi. Khi nào đi mua?"],["A","明天下午怎么样？你明天几点能回来？","Míngtiān xiàwǔ zěnmeyàng? nǐ míngtiān jǐdiǎn néng huílái?","Chiều mai được không? Ngày mai anh có thể về lúc mấy giờ?"],["B","三点多。","Sāndiǎn duō.","Hơn 3 giờ."]]},{"p":["在家里","Ở nhà"],"l":[["A","桌子下面有个猫。","Zhuōzi xiàmiàn yǒugè māo.","Ở dưới bàn có con mèo kìa."],["B","那是我的猫，它叫花花。","Nà shì wǒ de māo, tā jiào huāhuā.","Đó là con mèo của mình, nó tên là Hoa Hoa."],["A","它很漂亮。","Tā hěnpiàoliàng.","Con mèo này đẹp quá."],["B","是啊，我觉得它的眼睛最漂亮。","Shì a, wǒ juéde tā de yǎnjīng zuì piàoliàng.","Đúng vậy, mình nghĩ đôi mắt của nó đẹp nhất."],["A","它多大了？","Tā duō dà le?","Nó được bao nhiêu tuổi rồi?"],["B","六个多月。","Liùgè duōyuè.","Hơn 6 tháng tuổi."]]}]},{"n":2,"t":["我每天六点起床。","Wǒ měitiān liùdiǎn qǐchuáng.","Hàng ngày tôi thức dậy lúc 6 giờ."],"s":[{"p":["在运动场","Ở sân vận động"],"l":[["A","你很少生病，是不是喜欢运动？","Nǐ hěnshǎo shēngbìng, shìbúshì xǐhuān yùndòng?","Anh ít khi bị bệnh, chắc là anh thích tập thể dục phải không?"],["B","是啊，我每天早上都要出去跑步。","Shì a, wǒ měitiān zǎoshàng dōu yào chūqù pǎobù.","Đúng vậy. Mỗi buổi sáng tôi đều ra ngoài chạy bộ."],["A","你每天几点起床？","Nǐ měitiān jǐdiǎn qǐchuáng?","Hàng ngày anh thức dậy lúc mấy giờ?"],["B","我每天六点起床。","Wǒ měitiān liùdiǎn qǐchuáng.","6 giờ."]]},{"p":["在医院","Trong bệnh viện"],"l":[["A","吃药了吗？现在身体怎么样？","Chīyào le ma? xiànzài shēntǐ zěnmeyàng?","Cô uống thuốc chưa? Bây giờ cô thấy trong người thế nào?"],["B","吃了。现在好多了。","Chī le. xiànzài hǎoduō le.","Tôi uống rồi. Giờ thì tôi đã khỏe hơn nhiều."],["A","什么时候能出院？","Shénme shíhòu néng chūyuàn?","Khi nào cô có thể xuất viện?"],["B","医生说下个星期。","Yīshēng shuō xiàgèxīngqī.","Bác sĩ nói là tuần sau."]]},{"p":["在操场","Ở sân thể thao"],"l":[["A","大卫今年多大？","Dàwèi jīnnián duōdà?","David năm nay bao nhiêu tuổi vậy?"],["B","二十多岁。","Èrshíduōsuì.","Hơn 20 tuổi."],["A","他多高？","Tā duō gāo?","Thế anh ấy cao bao nhiêu?"],["B","一米八几。","Yīmǐ bājǐ.","Trên một mét tám mươi."],["A","你怎么知道这么多啊？","Nǐ zěnme zhīdào zhème duō a?","Sao bạn biết về anh ấy nhiều như vậy?"],["B","他是我同学。","Tā shì wǒ tóngxué.","Anh ấy học cùng lớp với mình mà."]]},{"p":["在房间","Trong phòng"],"l":[["A","张老师星期六也不休息啊？","Zhānglǎoshī xīngqīliù yě bù xiūxī a?","Thứ bảy mà thầy Trương cũng không nghỉ ngơi à?"],["B","是啊，他这几天很忙，没有时间休息。","Shì a, tā zhè jǐtiān hěn máng, méiyǒu shíjiān xiūxī.","Đúng vậy, mấy ngày nay anh ấy rất bận, không có thời gian nghỉ ngơi."],["A","那会很累吧？","Nàhuì hěn lèi ba?","Nếu thế thì chắc là anh ấy mệt lắm."],["B","他每天回来都很累。","Tā měitiān huílái dōu hěn lèi.","Ngày nào về đến nhà anh ấy cũng rất mệt."]]}]},{"n":3,"t":["左边那个红色的是我的。","Zuǒbiān nàge hóngsè de shì wǒ de.","Ly màu đỏ ở bên trái là của tôi."],"s":[{"p":["在房间","Trong phòng"],"l":[["A","这块手表是你的吗？","Zhèkuài shǒubiǎo shì nǐ de ma?","Chiếc đồng hồ đeo tay này là của anh phải không?"],["B","不是我的。是我爸爸的。","Búshì wǒ de. shì wǒ bàbà de.","Không phải, đồng hồ đó là của cha tôi."],["A","多少钱买的？","Duōshǎo qián mǎi de?","Mua hết bao nhiêu tiền vậy?"],["B","三千多块。","Sānqiānduōkuài.","Hơn 3.000 đồng."]]},{"p":["在家里","Ở nhà"],"l":[["A","这是今天早上的报纸吗？","Zhèshì jīntiān zǎoshàng de bàozhǐ ma?","Đây là báo ra sáng nay phải không?"],["B","不是，是昨天的。","Búshì, shì zuótiān de.","Không phải. Báo đó ra hôm qua."],["A","你听，是不是送报纸的来了？","Nǐ tīng, shìbúshì sòng bàozhǐ de lái le?","Em nghe thử xem, có phải người giao báo đến không?"],["B","我看一下。不是，是送牛奶的。","Wǒ kàn yīxià. búshì, shì sòng niúnǎi de.","Để em xem nào. Không phải đâu, đó là người giao sữa bò."]]},{"p":["在家里","Ở nhà"],"l":[["A","这是谁的房间？","Zhè shì shuí de fángjiān?","Đây là phòng của ai vậy?"],["B","这是我和我丈夫的，旁边那个小的房间是我女儿的。","Zhè shì wǒ hé wǒ zhàngfū de, pángbiān nàge xiǎo de fángjiān shì wǒ nǚér de.","Đó là phòng của vợ chồng tôi, còn phòng nhỏ bên cạnh là của con gái tôi."],["A","你女儿的房间真漂亮！都是粉色的。","Nǐ nǚér de fángjiān zhēn piàoliàng! dōu shì fěnsè de.","Phòng của con gái chị đẹp thật! Toàn là màu hồng."],["B","是啊，粉色是我女儿最喜欢的颜色。","Shì a, fěnsè shì wǒ nǚér zuì xǐhuān de yánsè.","Đúng vậy, con bé thích màu hồng nhất."]]},{"p":["在办公室","Trong văn phòng"],"l":[["A","你看见我的杯子了吗？","Nǐ kànjiàn wǒ de bēizi le ma?","Anh có thấy cái ly của tôi không?"],["B","这里有几个杯子，哪个是你的？","Zhèlǐ yǒu jǐgè bēizi, nǎge shì nǐ de?","Chỗ này có mấy cái ly, cái nào là của cô vậy?"],["A","左边那个红色的是我的。","Zuǒbiān nàge hóngsè de shì wǒ de.","Ly màu đỏ ở bên trái là của tôi."],["B","给你。","Gěi nǐ.","Ly của cô đây."]]}]},{"n":4,"t":["这个工作是他帮我介绍的。","Zhège gōngzuò shì tā bāng wǒ jièshào de.","Ông ấy đã giới thiệu giúp tôi công việc này."],"s":[{"p":["在教室","Trong lớp học"],"l":[["A","生日快乐！这是送给你的！","Shēngrìkuàilè! zhèshì sònggěi nǐ de!","Chúc sinh nhật vui vẻ! Đây là món quà mình tặng bạn."],["B","是什么？是一本书吗？","Shì shénme? shì yī běnshū ma?","Quà gì vậy? Có phải một quyển sách không?"],["A","对，这本书是我写的。","Duì, zhè běnshū shì wǒ xiě de.","Đúng vậy, quyển sách này là do mình viết đấy."],["B","太谢谢你了！","Tài xièxiè nǐ le!","Cảm ơn bạn nhiều lắm!"]]},{"p":["在家里","Ở nhà"],"l":[["A","早上有你一个电话。","Zǎoshàng yǒu nǐ yígè diànhuà.","Buổi sáng có người gọi điện cho anh đó."],["B","电话是谁打的？","Diànhuà shì shuí dǎ de?","Ai gọi vậy?"],["A","不知道，是儿子接的。","Bù zhīdào, shì érzi jiē de.","Em không biết nữa, con trai nghe điện thoại."],["B","好，晚上我问一下儿子。","Hǎo, wǎnshàng wǒ wèn yīxià érzi.","Được rồi, để tối anh sẽ hỏi con."]]},{"p":["在运动场","Ở sân vận động"],"l":[["A","你喜欢踢足球吗？","Nǐ xǐhuān tīzúqiú ma?","Anh có thích đá bóng không?"],["B","非常喜欢。","Fēicháng xǐhuān.","Rất thích."],["A","你是什么时候开始踢足球的？","Nǐ shì shénme shíhòu kāishǐ tīzúqiú de?","Anh bắt đầu đá bóng từ khi nào vậy?"],["B","我十一岁的时候开始踢足球，已经踢了十年了。","Wǒ shíyīsuì de shíhòu kāishǐ tīzúqiú, yǐjīng tī le shínián le.","Từ lúc 11 tuổi. Tôi đá bóng được 10 năm rồi."]]},{"p":["在公司","Trong công ty"],"l":[["A","你在这儿工作多长时间了？","Nǐ zài zhèér gōngzuò duōzhǎngshíjiān le?","Anh làm việc ở đây được bao lâu rồi?"],["B","已经两年多了，我是2011年来的。","Yǐjīng liǎngnián duō le, wǒ shì 2011 nián lái de.","Được hơn hai năm rồi. Tôi đến đây vào năm 2011."],["A","你认识谢先生吗？","Nǐ rènshí xièxiānshēng ma?","Anh có quen ông Tạ không?"],["B","认识，我们是大学同学，这个工作是他帮我介绍的。","Rènshí, wǒmen shì dàxué tóngxué, zhège gōngzuò shì tā bāng wǒ jièshào de.","Có quen, chúng tôi là bạn cùng lớp ở đại học. Ông ấy đã giới thiệu giúp tôi công việc này."]]}]},{"n":5,"t":["就买这件吧。","Jiù mǎi zhèjiàn ba.","Mua chiếc áo này đi."],"s":[{"p":["在家里","Ở nhà"],"l":[["A","晚上我们去饭馆吃饭，怎么样？","Wǎnshàng wǒmen qù fànguǎn chīfàn, zěnmeyàng?","Chúng ta đến quán ăn dùng cơm tối, được không em?"],["B","我不想去外面吃，我想在家吃。","Wǒ bùxiǎng qù wàimiàn chī, wǒ xiǎng zàijiā chī.","Em không muốn ăn ngoài, em muốn ăn ở nhà."],["A","那你准备做什么呢？","Nà nǐ zhǔnbèi zuò shénme ne?","Vậy em định nấu món gì?"],["B","就做你爱吃的鱼吧。","Jiù zuò nǐ ài chī de yú ba.","Thì nấu món cá mà anh thích ăn thôi."]]},{"p":["在商店","Ở cửa hàng"],"l":[["A","帮我看一下这件衣服怎么样。","Bāng wǒ kàn yīxià zhèjiàn yīfú zěnmeyàng.","Xem giúp mình chiếc áo này thế nào."],["B","颜色还可以，就是有点儿大。","Yánsè hái kěyǐ, jiùshì yǒudiǎnér dà.","Màu sắc cũng tạm được nhưng hơi rộng."],["A","这件小的怎么样？","Zhèjiàn xiǎo de zěnmeyàng?","Còn chiếc áo nhỏ này thì sao?"],["B","这件不错，就买这件吧。","Zhèjiàn bùcuò, jiù mǎi zhèjiàn ba.","Khá đẹp đấy. Mua chiếc áo này đi."]]},{"p":["在教室","Trong lớp học"],"l":[["A","今天去不去打球？","Jīntiān qùbùqù dǎqiú?","Hôm nay bạn đi chơi bóng không?"],["B","这两天有点儿累，不去打球了。","Zhè liǎngtiān yǒudiǎnér lèi, bùqù dǎqiú le.","Mình không đi đâu, mấy ngày nay mình hơi mệt."],["A","你在做什么呢？是在想昨天的考试吗？","Nǐ zài zuò shénme ne? shì zài xiǎng zuótiān de kǎoshì ma?","Bạn đang làm gì thế? Có phải đang nghĩ về bài kiểm tra hôm qua không?"],["B","是啊，我觉得听和说还可以，读和写不好，很多字我都不知道是什么意思。","Shì a, wǒ juéde tīng hé shuō hái kěyǐ, dú hé xiě bùhǎo, hěnduō zì wǒ dōu bù zhīdào shì shénme yìsi.","Đúng vậy, mình thấy mình làm bài nghe và nói cũng tạm được, nhưng làm bài đọc và viết không được tốt, có rất nhiều chữ mình không biết nghĩa."]]},{"p":["在公司","Trong công ty"],"l":[["A","休息一下吧，喝咖啡吗？","Xiūxī yīxià ba, hēkāfēi ma?","Nghỉ một chút đi, anh uống cà phê không?"],["B","不喝了，我已经喝两杯了。","Bù hē le, wǒ yǐjīng hē liǎngbēi le.","Không. Tôi đã uống hai ly rồi."],["A","是啊，咖啡喝多了对身体不好。","Shì a, kāfēi hēduō le duì shēntǐ bùhǎo.","Đúng đấy. Uống nhiều cà phê không tốt cho sức khỏe đâu."],["B","以后我少喝一点儿，每天喝一杯。","Yǐhòu wǒshǎo hē yìdiǎnér, měitiān hēyībēi.","Sau này tôi sẽ uống ít một chút, mỗi ngày chỉ một ly thôi."]]}]},{"n":6,"t":["你怎么不吃了？","Nǐ zěnme bùchī le?","Sao anh không ăn nữa?"],"s":[{"p":["在学校","Ở trường"],"l":[["A","你知道小王今天什么时候来学校吗？","Nǐ zhīdào xiǎowáng jīntiān shénme shíhòu lái xuéxiào ma?","Bạn có biết hôm nay cậu Vương sẽ đến trường khi nào không?"],["B","他已经来了。","Tā yǐjīng lái le.","Cậu ấy đã đến rồi."],["A","你怎么知道他来了？","Nǐ zěnme zhīdào tālái le?","Sao bạn biết cậu ấy đã đến?"],["B","我在门外看见他的自行车了。","Wǒ zài ménwài kànjiàn tā de zìxíngchē le.","Mình thấy xe đạp của cậu ấy ở ngoài cửa."]]},{"p":["在饭馆","Ở quán ăn"],"l":[["A","今天的羊肉很好吃，你怎么不吃了？","Jīntiān de yángròu hěn hǎochī, nǐ zěnme bùchī le?","Món thịt cừu hôm nay rất ngon, sao anh không ăn nữa?"],["B","这个星期天天都吃羊肉，不想吃了。","Zhège xīngqītiān tiān dōu chī yángròu, bùxiǎng chī le.","Tuần này ngày nào tôi cũng ăn thịt cừu nên chẳng muốn ăn nữa."],["A","那你还想吃什么？","Nà nǐ hái xiǎng chī shénme?","Vậy anh còn muốn ăn món gì?"],["B","来一点儿面条吧。","Lái yìdiǎnér miàntiáo ba.","Cho tôi mì sợi đi."]]},{"p":["在健身房","Ở phòng tập thể dục"],"l":[["A","昨天你们怎么都没去打篮球？","Zuótiān nǐmen zěnme dōu méi qù dǎlánqiú?","Hôm qua sao các anh không đi chơi bóng rổ?"],["B","因为昨天下雨，所以我们都没去。我去游泳了。","Yīnwèi zuótiān xiàyǔ, suǒyǐ wǒmen dōu méi qù. wǒ qù yóuyǒng le.","Chúng tôi không chơi vì hôm qua trời mưa. Nhưng tôi đi bơi."],["A","你经常游泳吗？","Nǐ jīngcháng yóuyǒng ma?","Anh có đi bơi thường xuyên không?"],["B","这个月我天天游泳，我现在七十公斤了。","Zhège yuè wǒ tiāntiān yóuyǒng, wǒ xiànzài qīshígōngjīn le.","Tháng này ngày nào tôi cũng đi bơi, hiện giờ tôi đã 70 kg rồi."]]},{"p":["在办公室","Trong văn phòng"],"l":[["A","这两天怎么没看见小张？","Zhè liǎngtiān zěnme méi kànjiàn xiǎozhāng?","Mấy ngày nay sao tôi không thấy anh Trương?"],["B","他去北京了。","Tā qù běijīng le.","Anh ấy đi Bắc Kinh rồi."],["A","去北京了？是去旅游吗？","Qù běijīng le? shì qù lǚyóu ma?","Đi Bắc Kinh à? Có phải đi du lịch không?"],["B","不是，听说是去看他姐姐。","Búshì, tīngshuō shì qù kàn tā jiějiě.","Không phải, nghe nói là đi thăm chị của anh ấy."]]}]},{"n":7,"t":["你家离公司远吗？","Nǐjiā lí gōngsī yuǎn ma?","Nhà chị có ở xa công ty không?"],"s":[{"p":["在家里","Ở nhà"],"l":[["A","大卫回来了吗？","Dàwèi huílái le ma?","David về chưa vậy?"],["B","没有，他还在教室学习呢。","Méiyǒu, tā hái zài jiàoshì xuéxí ne.","Chưa, anh ấy còn đang học trong lớp."],["A","已经9点多了，他怎么还在学习？","Yǐjīng 9 diǎnduō le, tā zěnme hái zài xuéxí?","Đã hơn 9 giờ rồi, sao còn đang học?"],["B","明天有考试，他说今天要好好准备。","Míngtiān yǒu kǎoshì, tā shuō jīntiān yào hǎohǎo zhǔnbèi.","Ngày mai có bài kiểm tra, anh ấy nói hôm nay phải chuẩn bị thật tốt."]]},{"p":["去机场的路上","Trên đường ra sân bay"],"l":[["A","你现在在哪儿呢？","Nǐ xiànzài zài nǎér ne?","Hiện giờ anh đang ở đâu vậy?"],["B","在去机场的路上。你已经到了吗？","Zài qù jīchǎng de lùshàng. nǐ yǐjīng dào le ma?","Đang trên đường ra sân bay. Em đến chưa?"],["A","我下飞机了。你还有多长时间能到这儿？","Wǒxià fēijī le. nǐ háiyǒu duōzhǎngshíjiān néng dào zhèér?","Em xuống máy bay rồi. Còn bao lâu nữa anh mới đến đây?"],["B","二十分钟就到。","Èrshífēnzhōng jiù dào.","20 phút nữa."]]},{"p":["在健身房","Ở phòng tập thể dục"],"l":[["A","你家离公司远吗？","Nǐjiā lí gōngsī yuǎn ma?","Nhà chị có ở xa công ty không?"],["B","很远，坐公共汽车要一个多小时呢！","Hěn yuǎn, zuò gōnggòngqìchē yào yígèduō xiǎoshí ne!","Rất xa, đi xe buýt phải mất hơn một giờ đồng hồ!"],["A","坐公共汽车太慢了，你怎么不开车？","Zuò gōnggòngqìchē tàimàn le, nǐ zěnme bù kāichē?","Đi xe buýt thì chậm quá, sao chị không lái xe?"],["B","开车也不快，路上车太多了！","Kāichē yě bùkuài, lùshàngchē tàiduō le!","Lái xe cũng chẳng nhanh được, trên đường có quá nhiều xe!"]]},{"p":["在路上","Trên đường"],"l":[["A","今天晚上我们一起吃饭吧，给你过生日。","Jīntiān wǎnshàng wǒmen yìqǐ chīfàn ba, gěi nǐ guòshēngrì.","Tối nay chúng ta cùng đi ăn cơm nhé, mừng sinh nhật bạn đó."],["B","今天？离我的生日还有一个多星期呢！","Jīntiān? lí wǒ de shēngrì háiyǒu yígèduō xīngqī ne!","Hôm nay à? Còn hơn một tuần nữa mới đến sinh nhật của mình mà!"],["A","下个星期我要去北京，今天过吧。","Xiàgèxīngqī wǒyào qù běijīng, jīntiān guò ba.","Tuần sau mình sẽ đi Bắc Kinh nên ăn mừng hôm nay đi."],["B","好吧，离这儿不远有一个中国饭馆，走几分钟就到了。","Hǎo ba, lí zhèér bùyuǎn yǒu yígè zhōngguó fànguǎn, zǒu jǐfēnzhōng jiù dào le.","Được thôi, gần đây có một quán ăn Trung Quốc, đi bộ vài phút là đến rồi."]]}]},{"n":8,"t":["让我想想再告诉你。","Ràng wǒ xiǎngxiǎng zài gàosù nǐ.","Để mình suy nghĩ rồi sẽ nói cho bạn biết."],"s":[{"p":["在教室","Trong lớp học"],"l":[["A","我们下午去看电影，好吗？","Wǒmen xiàwǔ qù kàn diànyǐng, hǎo ma?","Buổi chiều chúng ta đi xem phim được không?"],["B","今天下午我没有时间，明天下午再去吧。","Jīntiānxiàwǔ wǒ méiyǒu shíjiān, míngtiān xiàwǔ zài qù ba.","Chiều nay mình không rảnh rồi, chiều mai hãy đi vậy!"],["A","你想看什么电影？","Nǐ xiǎng kàn shénme diànyǐng?","Bạn muốn xem phim gì?"],["B","让我想想再告诉你。","Ràng wǒ xiǎngxiǎng zài gàosù nǐ.","Để mình suy nghĩ rồi sẽ nói cho bạn biết."]]},{"p":["在宿舍","Ở ký túc xá"],"l":[["A","外边天气很好，我们出去运动运动吧！","Wàibiān tiānqì hěn hǎo, wǒmen chūqù yùndòng yùndòng ba!","Bên ngoài trời rất đẹp, chúng ta ra ngoài tập thể dục một chút đi!"],["B","你等等我，好吗？王老师让我给大卫打个电话。","Nǐ děngděng wǒ, hǎo ma? wánglǎoshī ràng wǒ gěi dàwèi dǎgè diànhuà.","Cậu đợi mình một lát được không? Cô Vương bảo mình gọi điện cho David."],["A","回来再打吧。找大卫有什么事情吗？","Huílái zài dǎ ba. zhǎo dàwèi yǒu shénme shìqíng ma?","Khi nào quay về hãy gọi. Cậu tìm David có chuyện gì không?"],["B","听说大卫病了，我想找时间去看看他。","Tīngshuō dàwèi bìng le, wǒ xiǎng zhǎo shíjiān qù kànkàn tā.","Nghe nói David bị bệnh rồi. Mình định lúc nào rảnh sẽ đi thăm."]]},{"p":["在宾馆的前台","Tại quầy lễ tân của khách sạn"],"l":[["A","服务员，我房间的门打不开了。","Fúwùyuán, wǒ fángjiān de mén dǎbùkāi le.","Anh phục vụ ơi, ở phòng tôi cửa không mở được."],["B","您住哪个房间？","Nín zhù nǎge fángjiān?","Chị ở phòng nào ạ?"],["A","317。","317.","317."],["B","好的，我叫人去看看。","Hǎo de, wǒ jiào rén qù kànkàn.","Dạ được, tôi sẽ gọi người đến xem."]]},{"p":["在商店","Ở cửa hàng"],"l":[["A","你看看这几件衣服怎么样。","Nǐ kànkàn zhè jǐjiàn yīfú zěnmeyàng.","Cô xem xem mấy cái đầm này thế nào."],["B","这件白的有点儿长，那件黑的有点儿贵。","Zhèjiàn bái de yǒudiǎnér zhǎng, nàjiàn hēi de yǒudiǎnér guì.","Cái màu trắng này hơi dài còn cái màu đen kia hơi đắt."],["A","这件红的呢？这是今天新来的。","Zhèjiàn hóng de ne? zhèshì jīntiān xīnlái de.","Vậy cái màu đỏ này thì sao? Đây là hàng mới về hôm nay đấy."],["B","让我再看看。","Ràng wǒ zài kànkàn.","Để tôi xem đã."]]}]},{"n":9,"t":["题太多，我没做完。","Títàiduō, wǒ méi zuò wán.","Câu hỏi quá nhiều nên mình không làm hết."],"s":[{"p":["打电话","Gọi điện thoại"],"l":[["A","你好！请问张欢在吗？","Nǐhǎo! qǐngwèn zhānghuān zài ma?","Chào chị! Xin hỏi Trương Hoan có ở đó không?"],["B","你打错了，我们这儿没有叫张欢的。","Nǐ dǎcuò le, wǒmen zhèér méiyǒu jiào zhānghuān de.","Anh gọi nhầm số rồi, ở chỗ chúng tôi không có ai tên Trương Hoan cả."],["A","对不起。","Duìbùqǐ.","Xin lỗi chị."]]},{"p":["在学校","Ở trường"],"l":[["A","您从几岁开始学习跳舞？","Nín cóng jǐsuì kāishǐ xuéxí tiàowǔ?","Cô bắt đầu học múa từ lúc mấy tuổi vậy?"],["B","我第一次跳舞是在七岁的时候。","Wǒ dìyīcì tiàowǔ shì zài qīsuì de shíhòu.","Lần đầu tiên tôi múa là vào năm lên bảy tuổi."],["A","我女儿今年也七岁了。我希望她能跟您学跳舞，可以吗？","Wǒ nǚér jīnnián yě qīsuì le. wǒ xīwàng tā néng gēn nín xué tiàowǔ, kěyǐ ma?","Con gái tôi năm nay cũng được bảy tuổi rồi. Tôi mong là nó có thể học múa với cô, được không cô?"],["B","没问题，非常欢迎。","Méi wèntí, fēicháng huānyíng.","Không có vấn đề gì, tôi rất hoan nghênh."]]},{"p":["在家里","Ở nhà"],"l":[["A","你知道吗？大卫找到工作了。","Nǐ zhīdào ma? dàwèi zhǎodào gōngzuò le.","Chị biết không? David đã tìm được việc rồi."],["B","太好了！他从什么时候开始上班？","Tàihǎole! tā cóng shénme shíhòu kāishǐ shàngbān?","Tốt quá! Vậy khi nào thì nó bắt đầu đi làm?"],["A","从下个星期一开始。","Cóng xiàgèxīngqī yī kāishǐ.","Thứ hai tuần sau."],["B","这是他的第一个工作，希望他能喜欢。","Zhè shì tā de dìyígè gōngzuò, xīwàng tā néng xǐhuān.","Đây là công việc đầu tiên của nó, hy vọng nó sẽ thích."]]},{"p":["在教室","Trong lớp học"],"l":[["A","昨天的考试怎么样？你都听懂了吗？","Zuótiān de kǎoshì zěnmeyàng? nǐ dōu tīngdǒng le ma?","Bài kiểm tra hôm qua thế nào rồi? Bạn có hiểu hết những gì đã nghe không?"],["B","听懂了。","Tīngdǒng le.","Mình hiểu hết chứ."],["A","你都做完了没有？","Nǐ dōu zuò wán le méiyǒu?","Vậy bạn có làm hết không?"],["B","题太多，我没做完。","Títàiduō, wǒ méi zuò wán.","Câu hỏi quá nhiều nên mình không làm hết."]]}]},{"n":10,"t":["别找了，手机在桌子上呢。","Bié zhǎo le, shǒujī zài zhuōzi shàng ne.","Đừng tìm nữa, điện thoại ở trên bàn kìa."],"s":[{"p":["在家里","Ở nhà"],"l":[["A","不要看电视了，明天上午还有汉语课呢。","Búyào kàndiànshì le, míngtiān shàngwǔ háiyǒu hànyǔ kè ne.","Đừng xem tivi nữa, sáng mai các con còn có giờ học tiếng Trung Quốc đấy."],["B","看电视对学汉语有帮助。","Kàndiànshì duìxué hànyǔ yǒu bāngzhù.","Xem tivi cũng có ích cho việc học tiếng Trung Quốc mà."],["A","明天的课你都准备好了吗？","Míngtiān de kè nǐ dōu zhǔnbèi hǎolema?","Các con đã chuẩn bị xong bài ngày mai chưa?"],["B","都准备好了。","Dōu zhǔnbèi hǎo le.","Xong rồi ạ."]]},{"p":["在医院","Trong bệnh viện"],"l":[["A","别看报纸了，医生说你要多休息。","Biékàn bàozhǐ le, yīshēng shuō nǐ yào duō xiūxī.","Đừng đọc báo nữa, bác sĩ nói anh cần nghỉ ngơi nhiều hơn."],["B","好，不看了。给我一杯茶吧。","Hǎo, bùkàn le. gěi wǒ yībēi chá ba.","Được rồi, anh không đọc nữa. Cho anh một ly trà đi."],["A","医生说吃药后两个小时不要喝茶。","Yīshēng shuō chīyàohòu liǎnggè xiǎoshí búyào hēchá.","Bác sĩ nói anh không được uống trà trong vòng hai giờ sau khi uống thuốc."],["B","医生还说什么了？","Yīshēng hái shuō shénme le?","Bác sĩ còn dặn gì nữa không?"],["A","医生让你听我的。","Yīshēng ràng nǐ tīng wǒ de.","Bác sĩ bảo anh nghe lời em."]]},{"p":["在家里","Ở nhà"],"l":[["A","你怎么买了这么多东西啊？","Nǐ zěnme mǎi le zhème duō dōngxī a?","Sao anh mua nhiều thứ vậy?"],["B","哥哥今天中午回来吃饭。","Gēgē jīntiān zhōngwǔ huílái chīfàn.","Trưa nay anh trai về ăn cơm."],["A","我看看买什么了。羊肉、鸡蛋、面条、西瓜……真不少！妈妈呢？","Wǒ kànkàn mǎi shénme le. yángròu, jīdàn, miàntiáo, xīguā … … zhēnbùshǎo! māmā ne?","Để em xem anh mua gì nào. Thịt cừu, trứng gà, mì sợi, dưa hấu... Nhiều thật! Mẹ đâu rồi?"],["B","正在准备午饭呢！","Zhèngzài zhǔnbèi wǔfàn ne!","Mẹ đang chuẩn bị bữa trưa!"]]},{"p":["在家里","Ở nhà"],"l":[["A","你在找什么？","Nǐ zài zhǎo shénme?","Anh đang tìm gì vậy?"],["B","你看见我的手机了吗？白色的。","Nǐ kànjiàn wǒ de shǒujī le ma? báisè de.","Em có thấy điện thoại di động của anh không? Điện thoại màu trắng đó."],["A","别找了，手机在桌子上呢，电脑旁边。","Bié zhǎo le, shǒujī zài zhuōzi shàng ne, diànnǎo pángbiān.","Đừng tìm nữa, nó ở trên bàn kìa, bên cạnh máy vi tính."],["B","你看见我的衣服了吗？红色的那件。","Nǐ kànjiàn wǒ de yīfú le ma? hóngsè de nàjiàn.","Còn cái áo màu đỏ của anh, em có thấy không vậy?"],["A","那件衣服我帮你洗了，在外边呢。","Nà jiàn yīfú wǒ bāng nǐ xǐ le, zài wàibiān ne.","Em đã giặt giúp anh rồi, đang để bên ngoài."]]}]},{"n":11,"t":["他比我大三岁。","Tā bǐ wǒ dà sānsuì.","Anh ấy lớn hơn mình ba tuổi."],"s":[{"p":["在歌厅","Ở quán karaoke"],"l":[["A","王方，昨天和你一起唱歌的人是谁？","Wángfāng, zuótiān hé nǐ yìqǐ chànggē de rén shì shuí?","Vương Phương, người hát cùng với cô ngày hôm qua là ai thế?"],["B","一个朋友。","Yígè péngyǒu.","Một người bạn."],["A","什么朋友？是不是男朋友？","Shénme péngyǒu? shìbúshì nánpéngyǒu?","Bạn thế nào vậy? Có phải là bạn trai không?"],["B","不是不是，我同学介绍的，昨天第一次见。","Búshì búshì, wǒ tóngxué jièshào de, zuótiān dìyīcì jiàn.","Không, không phải đâu. Anh ấy là người mà bạn học tôi giới thiệu. Hôm qua là lần đầu tiên tôi gặp anh ấy đấy."]]},{"p":["在宿舍","Ở ký túc xá"],"l":[["A","左边这个看报纸的女孩子是你姐姐吗？","Zuǒbiān zhège kàn bàozhǐ de nǚháizi shì nǐ jiějiě ma?","Cô gái bên tay trái đang đọc báo là chị của bạn phải không?"],["B","是，右边写字的那个人是我哥哥。","Shì, yòubiān xiězì de nàge rén shì wǒ gēgē.","Đúng thế, còn người bên tay phải đang viết chữ là anh mình."],["A","你哥哥多大？","Nǐ gēgē duōdà?","Anh bạn bao nhiêu tuổi vậy?"],["B","25岁，他比我大三岁。","25 suì, tā bǐ wǒ dà sānsuì.","25 tuổi, anh ấy lớn hơn mình ba tuổi."]]},{"p":["在商店","Ở cửa hàng"],"l":[["A","今天的西瓜怎么卖？","Jīntiān de xīguā zěnme mài?","Dưa hấu hôm nay bán thế nào vậy?"],["B","三块五一斤。","Sānkuài wǔ yījīn.","Ba đồng năm hào nửa kí lô."],["A","比昨天便宜。","Bǐ zuótiān piányi.","Vậy là rẻ hơn hôm qua."],["B","是，苹果也比昨天便宜一些。您来点儿吧。","Shì, píngguǒ yě bǐ zuótiān piányi yīxiē. nín lái diǎnér ba.","Phải, táo cũng rẻ hơn hôm qua một chút. Ông mua một ít đi."]]},{"p":["在学校","Ở trường"],"l":[["A","前边说话的那个人就是我的汉语老师。你可能不认识她。","Qiánbiān shuōhuà de nàge rén jiùshì wǒ de hànyǔ lǎoshī. nǐ kěnéng bù rènshí tā.","Người đang nói chuyện ở phía trước chính là cô giáo dạy tôi tiếng Trung Quốc. Có lẽ anh không biết cô ấy."],["B","是新来的汉语老师吗？","Shì xīnlái de hànyǔ lǎoshī ma?","Có phải đó là cô giáo dạy tiếng Trung Quốc mới đến không?"],["A","是去年来的，她姓王，28岁。","Shì qùnián lái de, tā xìng wáng, 28 suì.","Đến vào năm ngoái, cô ấy họ Vương, 28 tuổi."],["B","她比我们老师小两岁。","Tā bǐ wǒmen lǎoshī xiǎo liǎngsuì.","Vậy là cô ấy nhỏ hơn cô giáo dạy chúng tôi hai tuổi."]]}]},{"n":12,"t":["你穿得太少了。","Nǐ chuān dé tàishǎo le.","Anh mặc ít quần áo quá."],"s":[{"p":["在教室","Trong lớp học"],"l":[["A","你每天早上几点起床？","Nǐ měitiān zǎoshàng jǐdiǎn qǐchuáng?","Mỗi sáng bạn thức dậy lúc mấy giờ vậy?"],["B","六点多。","Liùdiǎn duō.","Hơn 6 giờ."],["A","你比我早起一个小时。","Nǐ bǐ wǒ zǎoqǐ yígè xiǎoshí.","Bạn dậy sớm hơn mình một giờ rồi."],["B","我睡得也早，我每天晚上十点就睡觉。早睡早起身体好。","Wǒ shuì dé yě zǎo, wǒ měitiānwǎnshàng shídiǎn jiù shuìjiào. zǎoshuìzǎoqǐ shēntǐ hǎo.","Mình đi ngủ cũng sớm, vào lúc 10 giờ mỗi tối. Ngủ sớm dậy sớm tốt cho sức khỏe mà."]]},{"p":["在朋友家","Ở nhà bạn"],"l":[["A","再来点儿米饭吧，你吃得太少了。","Zài lái diǎnér mǐfàn ba, nǐ chī dé tàishǎo le.","Ăn thêm chút cơm đi, anh ăn ít quá."],["B","不少了，今天吃得很好，太谢谢你了。","Bùshǎo le, jīntiān chī dé hěn hǎo, tài xièxiè nǐ le.","Không ít đâu, hôm nay tôi ăn rất ngon miệng, cám ơn chị rất nhiều."],["A","你做饭做得怎么样？","Nǐ zuòfàn zuò dé zěnmeyàng?","Anh nấu ăn thế nào?"],["B","不怎么样，我妻子比我做得好。","Bùzěnmeyàng, wǒ qīzǐ bǐ wǒ zuòdéhǎo.","Chẳng ra làm sao, vợ tôi nấu ngon hơn tôi."]]},{"p":["在家门口","Ở trước cửa nhà"],"l":[["A","下雪了，今天真冷。","Xiàxuě le, jīntiān zhēnlěng.","Tuyết rơi rồi, hôm nay lạnh thật."],["B","有零下10度吧？","Yǒu língxià 10 dù ba?","Chắc là tới âm 10 độ phải không?"],["A","是啊，你穿得太少了，我们进房间吧。","Shì a, nǐ chuān dé tàishǎo le, wǒmen jìn fángjiān ba.","Đúng vậy, anh mặc ít quần áo quá, chúng ta vào nhà đi."],["B","好吧。","Hǎo ba.","Được thôi."]]},{"p":["在家里","Ở nhà"],"l":[["A","你在忙什么呢？","Nǐ zài máng shénme ne?","Bạn đang bận việc gì vậy?"],["B","我弟弟让我帮他找个房子，现在他家离公司有点儿远。","Wǒ dìdi ràng wǒ bāng tā zhǎogè fángzi, xiànzài tājiā lí gōngsī yǒudiǎnér yuǎn.","Cậu em trai nhờ mình tìm giúp một căn nhà, hiện giờ nhà nó hơi xa công ty."],["A","住得远真的很累！","Zhù dé yuǎn zhēnde hěnlèi!","Ở xa quả là rất mệt!"],["B","是啊，他也希望能住得近一点儿。","Shì a, tā yě xīwàng néngzhù dé jìn yìdiǎnér.","Đúng vậy, nó cũng mong có thể ở gần hơn một chút."]]}]},{"n":13,"t":["门开着呢。","Ménkāi zhe ne.","Cửa đang mở."],"s":[{"p":["在办公室","Trong văn phòng"],"l":[["A","门开着呢，请进。","Ménkāi zhe ne, qǐng jìn.","Cửa đang mở, mời vào."],["B","请问，张先生在吗？","Qǐngwèn, zhāng xiānshēng zài ma?","Cho tôi hỏi là ông Trương có ở đây không."],["A","他出去了。你下午再来吧。","Tā chūqù le. nǐ xiàwǔ zàilái ba.","Ông ấy ra ngoài rồi. Cô hãy quay lại vào buổi chiều nhé."],["B","好的，谢谢！","Hǎo de, xièxiè!","Được, cám ơn cô!"]]},{"p":["在办公室","Trong văn phòng"],"l":[["A","那个正在说话的女孩儿是谁？","Nàge zhèngzài shuōhuà de nǚháiér shì shuí?","Cô gái đang nói chuyện là ai vậy?"],["B","我知道她的名字，她姓杨，叫杨笑笑，她姐姐是我同学。","Wǒ zhīdào tā de míngzì, tā xìng yáng, jiào yáng xiàoxiào, tā jiějiě shì wǒ tóngxué.","Mình biết tên cô ấy. Cô ấy họ Dương, tên là Dương Tiếu Tiếu. Chị cô ấy là bạn học của mình."],["A","那个手里拿着铅笔的呢？","Nàge shǒulǐ ná zhe qiānbǐ de ne?","Còn cô gái đang cầm bút chì trong tay thì sao?"],["B","我不认识。","Wǒ bù rènshí.","Mình không biết cô ấy."]]},{"p":["在运动场","Ở sân vận động"],"l":[["A","听说你有女朋友了？我认识她吗？","Tīngshuō nǐ yǒu nǚpéngyǒu le? wǒ rènshí tā ma?","Nghe nói cậu đã có bạn gái rồi, phải vậy không? Mình có biết cô ấy không nhỉ?"],["B","就是我们班那个长着两个大眼睛，非常爱笑的女孩儿。","Jiùshì wǒmen bān nàge zhǎngzhe liǎnggè dà yǎnjīng, fēicháng àixiào de nǚháiér.","Đó là cô gái có đôi mắt to và rất hay cười. Cô ấy học ở lớp bọn mình đấy."],["A","她不是有男朋友吗？","Tā búshì yǒu nánpéngyǒu ma?","Chẳng phải cô ấy đã có bạn trai rồi sao?"],["B","那个已经是她的前男友了。","Nàge yǐjīng shì tā de qiánnányǒu le.","Người đó là bạn trai cũ rồi."]]},{"p":["在路上","Trên đường"],"l":[["A","请问，这儿离新京宾馆远吗？","Qǐngwèn, zhèér líxīnjīng bīnguǎn yuǎn ma?","Cho tôi hỏi là khách sạn Tân Kinh có ở xa chỗ này không."],["B","不远，走路二十分钟就到。","Bùyuǎn, zǒulù èrshífēnzhōng jiù dào.","Không xa đâu, đi bộ 20 phút là đến rồi."],["A","你能告诉我怎么走吗？","Nǐ néng gàosù wǒ zěnme zǒu ma?","Anh có thể cho tôi biết đi thế nào không?"],["B","从这儿一直往前走，到了前面的路口再往右走。","Cóng zhèér yìzhí wǎngqiánzǒu, dào le qiánmiàn de lùkǒu zài wǎngyòu zǒu.","Từ đây đi thẳng về phía trước, đến giao lộ thì rẽ phải."]]}]},{"n":14,"t":["你看过那个电影吗？","Nǐ kànguò nàge diànyǐng ma?","Cậu đã từng xem phim đó chưa?"],"s":[{"p":["在教室","Trong lớp học"],"l":[["A","你看过那个电影没有？","Nǐ kànguò nàge diànyǐng méiyǒu?","Cậu đã từng xem phim đó chưa?"],["B","没看过，听说很有意思。","Méi kànguò, tīngshuō hěn yǒuyìsi.","Chưa, nghe nói đây là bộ phim rất thú vị."],["A","那我们下个星期一起去看吧？","Nà wǒmen xiàgèxīngqī yìqǐ qù kànba?","Vậy tuần sau chúng ta cùng đi xem nhé?"],["B","可以，但是我女朋友也想去。","Kěyǐ, dànshì wǒ nǚpéngyǒu yě xiǎng qù.","Được, nhưng bạn gái của mình cũng muốn đi nữa."]]},{"p":["在办公室","Trong văn phòng"],"l":[["A","听说你去过中国，还想去吗？","Tīngshuō nǐ qùguò zhōngguó, hái xiǎng qù ma?","Nghe nói em đã từng đi Trung Quốc. Em có muốn đi nữa không?"],["B","我虽然去过好几次，但是还想再去玩儿玩儿。","Wǒ suīrán qùguò hǎo jǐcì, dànshì hái xiǎng zài qù wánér wánér.","Dù đã từng đi nhiều lần rồi nhưng em vẫn muốn đến đó chơi nữa."],["A","那我们一起去吧。","Nà wǒmen yìqǐ qù ba.","Vậy chúng ta cùng đi nhé."],["B","好啊，到时候我给你打电话。","Hǎo a, dàoshíhòu wǒ gěi nǐ dǎdiànhuà.","Được rồi, đến lúc ấy em sẽ gọi điện cho anh."]]},{"p":["在房间","Trong phòng"],"l":[["A","明天天气怎么样？","Míngtiān tiānqì zěnmeyàng?","Ngày mai thời tiết thế nào?"],["B","虽然是晴天，但是很冷。","Suīrán shì qíngtiān, dànshì hěn lěng.","Dù là ngày nắng ráo nhưng trời rất lạnh đấy."],["A","那还能去跑步吗？","Nà hái néng qù pǎobù ma?","Vậy thì ra ngoài chạy bộ có được không?"],["B","可以，但是你自己去吧，我还有很多事情要做。","Kěyǐ, dànshì nǐ zìjǐ qù ba, wǒ háiyǒu hěnduō shìqíng yào zuò.","Được, nhưng anh đi một mình nhé, em còn rất nhiều việc phải làm."]]},{"p":["在商店","Ở cửa hàng"],"l":[["A","你在这个商店买过东西没有？","Nǐ zài zhège shāngdiàn mǎiguò dōngxī méiyǒu?","Anh đã từng mua đồ ở cửa hàng này chưa?"],["B","买过一次，这儿的东西还可以，就是不便宜。","Mǎiguò yīcì, zhèér de dōngxī hái kěyǐ, jiùshì bù piányi.","Đã mua một lần rồi, đồ ở đây cũng được nhưng giá không rẻ đâu."],["A","我喜欢这件衣服，但是觉得有点儿贵。","Wǒ xǐhuān zhèjiàn yīfú, dànshì juéde yǒudiǎnér guì.","Em thích chiếc áo này nhưng thấy nó hơi đắt."],["B","两百块还可以，喜欢就买吧。","Liǎngbǎikuài hái kěyǐ, xǐhuān jiù mǎi ba.","Hai trăm đồng cũng được mà, nếu em thích thì mua đi."]]}]},{"n":15,"t":["新年就要到了。","Xīnnián jiùyào dào le.","Năm mới sắp đến rồi."],"s":[{"p":["在朋友家","Ở nhà bạn"],"l":[["A","今天是12月20日，新年就要到了。","Jīntiān shì 12 yuè 20 rì, xīnnián jiùyào dào le.","Hôm nay là ngày 20 tháng 12, năm mới sắp đến rồi."],["B","新年你准备做什么？","Xīnnián nǐ zhǔnbèi zuò shénme?","Bạn định làm gì vào năm mới vậy?"],["A","我想去北京旅游，北京很不错，我去过一次。","Wǒ xiǎng qù běijīng lǚyóu, běijīng hěn bùcuò, wǒ qùguò yīcì.","Mình muốn đi du lịch ở Bắc Kinh. Bắc Kinh rất tuyệt, mình từng đến đó một lần."],["B","你买票了吗？","Nǐ mǎipiào le ma?","Bạn đã mua vé chưa?"],["A","还没有呢，明天就去火车站买票。","Hái méiyǒu ne, míngtiān jiù qù huǒchēzhàn mǎipiào.","Chưa, ngày mai mình sẽ đến ga tàu hỏa để mua."]]},{"p":["在公司","Trong công ty"],"l":[["A","时间过得真快，新的一年快要到了！","Shíjiān guòdé zhēnkuài, xīn de yīnián kuàiyào dào le!","Thời gian trôi qua nhanh thật, năm mới sắp đến rồi!"],["B","是啊，谢谢大家这一年对我的帮助！","Shì a, xièxiè dàjiā zhè yīnián duì wǒ de bāngzhù!","Đúng vậy, cám ơn mọi người vì đã giúp đỡ tôi trong suốt năm nay!"],["C","希望我们的公司明年更好！","Xīwàng wǒmen de gōngsī míngnián gènghǎo!","Hy vọng sang năm công ty của chúng ta sẽ phát triển hơn nữa!"]]},{"p":["在车站","Ở bến xe"],"l":[["A","你妹妹怎么还没来？都八点四十了！","Nǐ mèimèi zěnme hái méilái? dōu bādiǎn sìshí le!","Em gái của em sao vẫn chưa đến vậy? Đã 8 giờ 40 phút rồi!"],["B","我们再等她几分钟吧。","Wǒmen zài děng tā jǐfēnzhōng ba.","Chúng ta đợi em ấy vài phút nữa đi."],["A","都等她半个小时了！","Dōu děng tā bàngè xiǎoshí le!","Đã đợi nửa giờ đồng hồ rồi!"],["B","她来了，我听见她说话了。","Tā lái le, wǒ tīngjiàn tā shuōhuà le.","Em ấy đến rồi, em nghe thấy tiếng nó rồi."]]},{"p":["在咖啡馆门口","Ở trước quán cà phê"],"l":[["A","天阴了，我要回去了。","Tiānyīn le, wǒyào huíqù le.","Trời u ám rồi, anh phải về đây."],["B","好的。快要下雨了，你路上慢点儿。","Hǎo de. kuàiyào xiàyǔ le, nǐ lùshàng màndiǎnér.","Vâng. Trời sắp mưa rồi đó. Trên đường, anh đi chậm thôi nhé."],["A","没关系，我坐公共汽车。","Méiguānxì, wǒ zuò gōnggòngqìchē.","Không sao đâu, anh sẽ đi xe buýt."],["B","好的。再见。","Hǎo de. zàijiàn.","Vậy thì tốt. Tạm biệt."]]}]}],3:[{"n":1,"t":["周末你有什么打算？","Zhōumò nǐ yǒu shénme dǎsuàn?","Anh dự định làm gì vào cuối tuần vậy?"],"s":[{"p":["谈周末的打算","Nói về kế hoạch cuối tuần"],"l":[["小丽","周末你有什么打算？","Zhōumò nǐ yǒu shénme dǎsuàn?","Cuối tuần anh có dự định gì không?"],["小刚","我早就想好了，请你吃饭、看电影、喝咖啡。","Wǒ zǎojiù xiǎng hǎo le, qǐng nǐ chīfàn, kàn diànyǐng, hēkāfēi.","Anh đã nghĩ sẵn từ lâu rồi: mời em ăn cơm, xem phim, uống cà phê."],["小丽","请我？","Qǐng wǒ?","Mời em à?"],["小刚","是啊，我已经找好饭馆儿了，电影票也买好了。","Shì a, wǒ yǐjīng zhǎo hǎo fànguǎnér le, diànyǐngpiào yě mǎihǎo le.","Đúng vậy, anh đã tìm được quán ăn rồi, vé xem phim cũng mua xong rồi."],["小丽","我还没想好要不要跟你去呢。","Wǒ hái méixiǎng hǎo yào búyào gēn nǐ qù ne.","Em còn chưa nghĩ xong có đi cùng anh hay không đâu."]]},{"p":["在家","Ở nhà"],"l":[["妈妈","你一直玩儿电脑游戏，作业写完了吗？","Nǐ yìzhí wánér diànnǎoyóuxì, zuòyè xiě wán le ma?","Con chơi điện tử suốt, bài tập viết xong chưa?"],["儿子","都写完了。","Dōu xiě wán le.","Viết xong hết rồi ạ."],["妈妈","明天不是有考试吗？你怎么一点儿也不着急？","Míngtiān búshì yǒu kǎoshì ma? nǐ zěnme yìdiǎnér yě bù zháojí?","Mai chẳng phải có bài thi sao? Sao con chẳng sốt ruột chút nào vậy?"],["儿子","我早就复习好了。","Wǒ zǎojiù fùxí hǎo le.","Con ôn xong từ lâu rồi."],["妈妈","那也不能一直玩儿啊。","Nà yě bùnéng yìzhí wánér a.","Thế cũng không thể chơi mãi được."]]},{"p":["聊旅游计划","Nói về kế hoạch đi du lịch"],"l":[["小丽","下个月我去旅游，你能跟我一起去吗？","Xiàgèyuè wǒ qù lǚyóu, nǐ néng gēn wǒ yìqǐ qù ma?","Tháng sau em đi du lịch, anh có thể đi cùng em không?"],["小刚","我还没想好呢。你觉得哪儿最好玩儿？","Wǒ hái méixiǎng hǎo ne. nǐ juéde nǎér zuì hǎowánér?","Anh còn chưa nghĩ ra. Em thấy chỗ nào vui nhất?"],["小丽","南方啊，我们去年就是这个时候去的。","Nánfāng a, wǒmen qùnián jiùshì zhège shíhòu qù de.","Miền nam đó, năm ngoái chúng ta cũng đi vào thời gian này."],["小刚","南方太热了，北方好一些，不冷也不热。","Nánfāng tàirè le, běifāng hǎo yīxiē, bùlěng yě bù rè.","Miền nam nóng quá, miền bắc tốt hơn một chút, không lạnh cũng không nóng."]]},{"p":["准备去旅游","Chuẩn bị đi du lịch"],"l":[["小刚","水果、面包、茶都准备好了，我们还带什么？","Shuǐguǒ, miànbāo, chá dōu zhǔnbèi hǎo le, wǒmen hái dài shénme?","Hoa quả, bánh mì, trà đều chuẩn bị xong rồi, chúng ta còn mang gì nữa?"],["小丽","手机、电脑、地图，一个也不能少。","Shǒujī, diànnǎo, dìtú, yígè yě bùnéng shǎo.","Điện thoại, máy tính, bản đồ, không được thiếu thứ nào."],["小刚","这些我昨天下午就准备好了。","Zhèxiē wǒ zuótiānxiàwǔ jiù zhǔnbèi hǎo le.","Mấy thứ này anh đã chuẩn bị xong từ chiều hôm qua rồi."],["小丽","再多带几件衣服吧。","Zài duō dài jǐjiàn yīfú ba.","Mang thêm vài bộ quần áo nữa đi."],["小刚","我们是去旅游，不是搬家，还是少带一些吧。","Wǒmen shì qù lǚyóu, búshì bānjiā, háishì shǎodài yīxiē ba.","Chúng ta đi du lịch chứ có phải chuyển nhà đâu, vẫn nên mang ít thôi."]]}]},{"n":2,"t":["他什么时候回来？","Tā shénme shíhòu huílái?","Khi nào anh ấy quay về?"],"s":[{"p":["下山的路上","Trên đường xuống núi"],"l":[["小丽","休息一下吧。","Xiūxī yīxià ba.","Nghỉ một chút đi."],["小刚","怎么了？","Zěnme le?","Sao thế?"],["小丽","我现在腿也疼，脚也疼。","Wǒ xiànzài tuǐ yě téng, jiǎo yě téng.","Bây giờ chân em vừa đau, bàn chân cũng đau."],["小刚","好，那边树多，我们过去坐一下吧。","Hǎo, nàbiān shùduō, wǒmen guòqù zuò yīxià ba.","Được, bên kia nhiều cây, chúng ta qua đó ngồi một lát."],["小丽","上来的时候我怎么没觉得这么累？","Shànglái de shíhòu wǒ zěnme méi juéde zhème lèi?","Lúc leo lên sao em không thấy mệt thế này nhỉ?"],["小刚","上山容易下山难，你不知道？","Shàngshān róngyì xiàshān nán, nǐ bù zhīdào?","Lên núi thì dễ, xuống núi mới khó, em không biết à?"]]},{"p":["在打电话","Đang gọi điện thoại"],"l":[["周太太","喂，你好，请问周明在吗？","Wèi, nǐhǎo, qǐngwèn zhōumíng zài ma?","A lô, chào cô, xin hỏi Châu Minh có ở đó không?"],["秘书","周经理出去了，不在办公室。","Zhōu jīnglǐ chūqù le, bù zài bàngōngshì.","Giám đốc Châu ra ngoài rồi, không có ở văn phòng."],["周太太","他去哪儿了？什么时候回来？","Tā qù nǎér le? shénme shíhòu huílái?","Anh ấy đi đâu? Khi nào về?"],["秘书","他出去办事了，下午回来。","Tā chūqù bànshì le, xiàwǔ huílái.","Ông ấy ra ngoài làm việc, buổi chiều sẽ về."],["周太太","回来了就让他给我打个电话。","Huílái le jiùràng tā gěi wǒ dǎgè diànhuà.","Về rồi thì bảo anh ấy gọi điện cho tôi nhé."],["秘书","好的，他到了办公室我就告诉他。","Hǎo de, tā dào le bàngōngshì wǒ jiù gàosù tā.","Vâng, ông ấy đến văn phòng là tôi báo ngay."]]},{"p":["在楼门口送朋友","Tiễn bạn ở trước cửa tòa nhà"],"l":[["小刚","雨下得真大。你怎么回去？我送你吧。","Yǔxià dé zhēndà. nǐ zěnme huíqù? wǒ sòng nǐ ba.","Mưa to thật. Em về bằng cách nào? Anh đưa em về nhé."],["小丽","没事，我出去叫辆出租车就行了。","Méishì, wǒ chūqù jiàoliàng chūzūchē jiùxíngle.","Không sao, em ra gọi một chiếc taxi là được."],["小刚","那你等等，我上楼去给你拿把伞。","Nà nǐ děngděng, wǒ shànglóuqù gěi nǐ ná bǎ sǎn.","Vậy em đợi chút, anh lên lầu lấy cho em cái ô."],["小丽","好的。我跟你一起上去吧。","Hǎo de. wǒ gēn nǐ yìqǐ shàngqù ba.","Được. Em lên cùng anh nhé."],["小刚","你在这儿等吧，我拿了伞就下来。","Nǐ zài zhèér děng ba, wǒ ná le sǎn jiù xiàlái.","Em đợi ở đây đi, anh lấy ô xong sẽ xuống ngay."]]},{"p":["在家","Ở nhà"],"l":[["周太太","你看，我这么胖，怎么办呢？","Nǐ kàn, wǒ zhème pàng, zěnmebàn ne?","Anh xem, em béo thế này, làm sao bây giờ?"],["周明","你每天晚上吃了饭就睡觉，也不出去走走，能不胖吗？","Nǐ měitiānwǎnshàng chīlefàn jiù shuìjiào, yě bù chūqù zǒuzǒu, néng bù pàng ma?","Tối nào em ăn xong cũng đi ngủ, cũng chẳng ra ngoài đi dạo, không béo sao được?"],["周太太","其实我每天都运动。","Qíshí wǒ měitiān dōu yùndòng.","Thật ra ngày nào em cũng vận động."],["周明","但是你一点儿也没瘦！你做什么运动了？","Dànshì nǐ yìdiǎnér yě méi shòu! nǐ zuò shénme yùndòng le?","Nhưng em chẳng gầy đi chút nào! Em vận động gì vậy?"],["周太太","做饭啊。","Zuòfàn a.","Nấu cơm đó."]]}]},{"n":3,"t":["桌子上放着很多饮料。","Zhuōzi shàngfàng zhe hěnduō yǐnliào.","Trên bàn có rất nhiều thức uống."],"s":[{"p":["在小丽家","Ở nhà của chị Lệ"],"l":[["小刚","明天是晴天还是阴天？","Míngtiān shì qíngtiān háishì yīntiān?","Ngày mai trời nắng hay âm u?"],["小丽","阴天，电视上说多云。怎么了？有事？","Yīntiān, diànshì shàng shuō duōyún. zěnme le? yǒushì?","Âm u, tivi nói là nhiều mây. Sao thế? Có việc à?"],["小刚","没事，我们明天要去爬山。","Méishì, wǒmen míngtiān yào qù páshān.","Không có gì, ngày mai bọn anh định đi leo núi."],["小丽","爬山的时候要小心点儿。","Páshān de shíhòu yào xiǎoxīn diǎnér.","Lúc leo núi phải cẩn thận một chút."],["小刚","好，你也去吗？","Hǎo, nǐ yě qù ma?","Ừ, em cũng đi chứ?"],["小丽","我不去，我有事。","Wǒ bù qù, wǒ yǒushì.","Em không đi, em có việc."]]},{"p":["在商场","Ở cửa hàng bách hóa"],"l":[["周太太","你觉得这条裤子怎么样？","Nǐ juéde zhè tiáo kùzi zěnmeyàng?","Anh thấy cái quần này thế nào?"],["周明","我记得你已经有两条这样的裤子了。","Wǒ jìde nǐ yǐjīng yǒu liǎngtiáo zhèyàng de kùzi le.","Anh nhớ là em đã có hai cái quần như thế này rồi."],["周太太","那我们再看看别的。","Nà wǒmen zài kànkàn biéde.","Vậy chúng ta xem cái khác nữa."],["周明","这件衬衫怎么样？","Zhèjiàn chènshān zěnmeyàng?","Chiếc áo sơ mi này thế nào?"],["周太太","还不错，多少钱？","Hái bùcuò, duōshǎo qián?","Cũng được đấy, bao nhiêu tiền?"],["周明","这上面写着320元。","Zhè shàngmiàn xiě zhe 320 yuán.","Trên này ghi 320 đồng."],["周太太","买一件。","Mǎi yījiàn.","Mua một chiếc."]]},{"p":["在水果店","Ở cửa hàng trái cây"],"l":[["周太太","这些水果真新鲜，我们买西瓜还是苹果？","Zhèxiē shuǐguǒ zhēn xīnxiān, wǒmen mǎi xīguā háishì píngguǒ?","Hoa quả này tươi thật, chúng ta mua dưa hấu hay táo?"],["周明","西瓜吧。你看，这上面写着“西瓜不甜不要钱”。","Xīguā ba. nǐ kàn, zhè shàngmiàn xiě zhe \" xīguā bùtián búyào qián \".","Dưa hấu đi. Em xem, trên này ghi \"Dưa không ngọt không lấy tiền\"."],["周太太","那我们买一个大点儿的吧。","Nà wǒmen mǎi yígè dà diǎnér de ba.","Vậy chúng ta mua một quả to một chút nhé."],["周明","再买几个苹果。","Zài mǎi jǐgè píngguǒ.","Mua thêm mấy quả táo nữa."],["周太太","好啊，今天晚上只吃水果不吃饭！","Hǎo a, jīntiān wǎnshàng zhǐ chīshuǐguǒ bù chīfàn!","Được, tối nay chỉ ăn hoa quả không ăn cơm!"]]},{"p":["在休息室","Trong phòng giải lao"],"l":[["小丽","桌子上放着很多饮料，你喝什么？","Zhuōzi shàngfàng zhe hěnduō yǐnliào, nǐ hē shénme?","Trên bàn có rất nhiều đồ uống, anh uống gì?"],["小刚","茶或者咖啡都可以。你呢？你喝什么？","Chá huòzhě kāfēi dōu kěyǐ. nǐ ne? nǐ hē shénme?","Trà hoặc cà phê đều được. Còn em? Em uống gì?"],["小丽","我喝茶，茶是我的最爱。天冷了或者工作累了的时候，喝杯热茶会很舒服。","Wǒ hēchá, chá shì wǒ de zuì ài. tiānlěng le huòzhě gōngzuò lèi le de shíhòu, hēbēi rèchá huì hěn shūfú.","Em uống trà, trà là thứ em thích nhất. Khi trời lạnh hoặc làm việc mệt, uống một ly trà nóng sẽ rất dễ chịu."],["小刚","你喜欢喝什么茶？","Nǐ xǐhuān hē shénme chá?","Em thích uống trà gì?"],["小丽","花茶、绿茶、红茶，我都喜欢。","Huāchá, lǜchá, hóngchá, wǒ dōu xǐhuān.","Trà hoa, trà xanh, hồng trà, em đều thích."]]}]},{"n":4,"t":["她总是笑着跟客人说话。","Tā zǒngshì xiào zhe gēn kèrén shuōhuà.","Cô ấy luôn cười khi nói chuyện với khách hàng."],"s":[{"p":["在教室","Trong lớp học"],"l":[["小明","这是你们比赛的照片吗？","Zhèshì nǐmen bǐsài de zhàopiān ma?","Đây là ảnh cuộc thi của các bạn à?"],["马可","是，这是我们比赛后照的。","Shì, zhèshì wǒmen bǐsài hòuzhào de.","Đúng, đây là ảnh bọn mình chụp sau cuộc thi."],["小明","照得不错，你们都是一个年级的吗？","Zhào dé bùcuò, nǐmen dōu shì yígè niánjí de ma?","Chụp đẹp đấy, các bạn đều học cùng một khối à?"],["马可","不是。那个又高又漂亮的女孩儿是二年级的。","Búshì. nàge yòu gāo yòu piàoliàng de nǚháiér shì èrniánjí de.","Không phải. Cô gái vừa cao vừa xinh kia học năm hai."],["小明","旁边那个拿着书笑的人是谁？","Pángbiān nàge ná zhe shū xiào de rén shì shuí?","Người đứng bên cạnh cầm sách cười là ai vậy?"],["马可","那是我！","Nà shì wǒ!","Là mình đó!"]]},{"p":["在教室","Trong lớp học"],"l":[["小丽","你觉得小红怎么样？","Nǐ juéde xiǎohóng zěnmeyàng?","Bạn thấy Tiểu Hồng thế nào?"],["同学","她又聪明又热情，也很努力。","Tā yòu cōngmíng yòu rèqíng, yě hěn nǔlì.","Cô ấy vừa thông minh vừa nhiệt tình, cũng rất chăm chỉ."],["小丽","我看她总是笑着回答老师的问题。","Wǒ kàn tā zǒngshì xiào zhe huídá lǎoshī de wèntí.","Mình thấy cô ấy lúc nào cũng mỉm cười trả lời câu hỏi của thầy cô."],["同学","她对每个人都笑，也常常对我笑。","Tā duì měigè rén dōu xiào, yě chángcháng duì wǒ xiào.","Cô ấy cười với mọi người, cũng thường cười với mình."],["小丽","你是不是喜欢她啊？","Nǐ shìbúshì xǐhuān tā a?","Có phải bạn thích cô ấy không?"],["同学","喜欢她的人太多了，你看那些拿着鲜花站在门口的，都是等她的。","Xǐhuān tā de réntàiduō le, nǐ kàn nàxiē ná zhe xiānhuā zhàn zài ménkǒu de, dōu shì děng tā de.","Người thích cô ấy nhiều lắm, bạn xem những người cầm hoa đứng ở cửa kia, đều là đợi cô ấy đó."]]},{"p":["在超市门口","Ở trước cửa siêu thị"],"l":[["小刚","我有点儿饿了，我们进超市买点儿东西吧。","Wǒ yǒudiǎnér è le, wǒmen jìn chāoshì mǎidiǎnér dōngxī ba.","Anh hơi đói rồi, chúng ta vào siêu thị mua ít đồ nhé."],["小丽","好啊，这家超市的蛋糕又便宜又好吃，一块只要2.99元。","Hǎo a, zhèjiā chāoshì de dàngāo yòu piányi yòu hǎochī, yīkuài zhǐyào 2.99 yuán.","Được, bánh kem ở siêu thị này vừa rẻ vừa ngon, một miếng chỉ 2,99 đồng."],["小刚","我们买两块儿，回家吃着蛋糕看电视，怎么样？","Wǒmen mǎi liǎngkuài ér, huíjiā chī zhe dàngāo kàndiànshì, zěnmeyàng?","Chúng ta mua hai miếng, về nhà vừa ăn bánh vừa xem tivi, được không?"],["小丽","好啊，我再去买一些喝的。","Hǎo a, wǒ zài qù mǎi yīxiē hē de.","Được, em đi mua thêm ít đồ uống."],["小刚","喝着咖啡吃蛋糕，太好了！","Hē zhe kāfēi chī dàngāo, tàihǎole!","Vừa uống cà phê vừa ăn bánh, tuyệt quá!"]]},{"p":["在饭馆儿","Ở quán ăn"],"l":[["经理","您好！您找谁？","Nínhǎo! nín zhǎo shuí?","Chào anh! Anh tìm ai?"],["客人","你们这儿是不是有一个又年轻又漂亮的服务员？","Nǐmen zhèér shìbúshì yǒu yígè yòu niánqīng yòu piàoliàng de fúwùyuán?","Ở đây có phải có một cô phục vụ vừa trẻ vừa xinh không?"],["经理","我们这儿年轻、漂亮的服务员有很多。","Wǒmen zhèér niánqīng, piàoliàng de fúwùyuán yǒu hěnduō.","Ở đây chúng tôi có nhiều cô phục vụ trẻ đẹp lắm."],["客人","她工作又认真又热情。","Tā gōngzuò yòu rènzhēn yòu rèqíng.","Cô ấy làm việc vừa nghiêm túc vừa nhiệt tình."],["经理","您能再说说吗？","Nín néng zàishuō shuō ma?","Anh có thể nói thêm không?"],["客人","她总是笑着跟客人说话。","Tā zǒngshì xiào zhe gēn kèrén shuōhuà.","Cô ấy luôn mỉm cười khi nói chuyện với khách."],["经理","啊，我知道了，你说的是李小美吧？","A, wǒ zhīdào le, nǐ shuō de shì lǐxiǎoměi ba?","À, tôi biết rồi, anh nói Lý Tiểu Mỹ phải không?"]]}]},{"n":5,"t":["我最近越来越胖了。","Wǒ zuìjìn yuèláiyuè pàng le.","Dạo này em càng ngày càng béo."],"s":[{"p":["在小丽家","Tại nhà chị Lệ"],"l":[["朋友","我听说你身体不舒服，怎么了？","Wǒ tīngshuō nǐ shēntǐ bù shūfú, zěnme le?","Mình nghe nói bạn không khỏe, sao vậy?"],["小丽","前几天有点儿发烧，现在好多了。","Qián jǐtiān yǒudiǎnér fāshāo, xiànzài hǎoduō le.","Mấy hôm trước hơi sốt, bây giờ đỡ nhiều rồi."],["朋友","喝杯茶吧，这是我为你买的绿茶，很不错。","Hēbēi chá ba, zhè shì wǒ wèi nǐ mǎi de lǜchá, hěn bùcuò.","Uống chén trà đi, đây là trà xanh mình mua cho bạn, ngon lắm."],["小丽","谢谢，我要吃药，不喝茶了。","Xièxiè, wǒyào chīyào, bù hēchá le.","Cảm ơn, mình phải uống thuốc nên không uống trà."],["朋友","那喝杯水吧。","Nà hē bēishuǐ ba.","Vậy uống cốc nước nhé."],["小丽","好的。","Hǎo de.","Được."]]},{"p":["在打电话","Nói chuyện qua điện thoại"],"l":[["周太太","对不起，我明天不能和你们出去玩儿了。","Duìbùqǐ, wǒ míngtiān bùnéng hé nǐmen chūqù wánér le.","Xin lỗi, ngày mai tôi không đi chơi cùng các chị được rồi."],["张太太","为什么？怎么了？","Wèishénme? zěnme le?","Tại sao? Có chuyện gì vậy?"],["周太太","我儿子生病了，我要在家照顾他。","Wǒ érzi shēngbìng le, wǒyào zàijiā zhàogù tā.","Con trai tôi bị ốm, tôi phải ở nhà chăm sóc nó."],["张太太","他吃药了吗？要不要去医院？","Tā chīyào le ma? yào búyào qù yīyuàn?","Cháu uống thuốc chưa? Có cần đi bệnh viện không?"],["周太太","不用去医院，昨天吃了感冒药，现在好一些了。","Bùyòng qù yīyuàn, zuótiān chī le gǎnmàoyào, xiànzài hǎo yīxiē le.","Không cần đi bệnh viện, hôm qua uống thuốc cảm rồi, giờ đỡ hơn một chút."],["张太太","那我们下次再一起出去玩儿吧。","Nà wǒmen xiàcì zài yìqǐ chūqù wánér ba.","Vậy lần sau chúng ta lại cùng đi chơi nhé."]]},{"p":["在小刚家","Tại nhà anh Cương"],"l":[["小丽","你最喜欢哪个季节？","Nǐ zuì xǐhuān nǎge jìjié?","Anh thích mùa nào nhất?"],["小刚","当然是春天，天气不那么冷了，草和树都绿了，花也开了。","Dāngrán shì chūntiān, tiānqì bù nàme lěng le, cǎohéshù dōu lǜ le, huā yě kāi le.","Đương nhiên là mùa xuân, trời không lạnh như thế nữa, cỏ cây đều xanh, hoa cũng nở rồi."],["小丽","我最喜欢夏天，因为我可以穿漂亮的裙子了。","Wǒ zuì xǐhuān xiàtiān, yīnwèi wǒ kěyǐ chuān piàoliàng de qúnzi le.","Em thích mùa hè nhất, vì em có thể mặc váy đẹp."],["小刚","那我也喜欢夏天了。","Nà wǒ yě xǐhuān xiàtiān le.","Vậy anh cũng thích mùa hè rồi."],["小丽","怎么？你也有漂亮的裙子？","Zěnme? nǐ yě yǒu piàoliàng de qúnzi?","Sao thế? Anh cũng có váy đẹp à?"],["小刚","不，我喜欢看你穿漂亮的裙子。","Bù, wǒ xǐhuān kàn nǐ chuān piàoliàng de qúnzi.","Không, anh thích ngắm em mặc váy đẹp."]]},{"p":["在小刚家","Tại nhà anh Cương"],"l":[["小丽","我最近越来越胖了。","Wǒ zuìjìn yuèláiyuè pàng le.","Dạo này em càng ngày càng béo."],["小刚","谁说的？我觉得你越来越漂亮了。","Shuí shuō de? wǒ juéde nǐ yuèláiyuè piàoliàng le.","Ai nói thế? Anh thấy em càng ngày càng xinh."],["小丽","你看，这条裙子是去年买的，今年就不能穿了。","Nǐ kàn, zhè tiáo qúnzi shì qùnián mǎi de, jīnnián jiù bùnéng chuān le.","Anh xem, chiếc váy này mua năm ngoái, năm nay đã không mặc vừa nữa rồi."],["小刚","那是因为你吃得太多了，少吃点儿吧。","Nà shìyīnwèi nǐ chī dé tài duō le, shǎo chī diǎnér ba.","Đó là vì em ăn nhiều quá, ăn ít đi một chút."],["小丽","我做的饭越来越好吃，我能少吃吗？","Wǒ zuò de fàn yuèláiyuè hǎochī, wǒnéng shǎo chī ma?","Cơm em nấu càng ngày càng ngon, em ăn ít được sao?"]]}]},{"n":6,"t":["怎么突然找不到了？","Zěnme tūrán zhǎo búdào le?","Sao bỗng dưng lại không tìm thấy?"],"s":[{"p":["在客厅","Trong phòng khách"],"l":[["周明","我的眼镜呢？怎么突然找不到了？你看见了吗？","Wǒ de yǎnjìng ne? zěnme tūrán zhǎo búdào le? nǐ kànjiàn le ma?","Kính của anh đâu? Sao bỗng dưng không tìm thấy? Em có thấy không?"],["周太太","我没看见啊。","Wǒ méi kànjiàn a.","Em không thấy."],["周明","我离不开眼镜，没有眼镜，我一个字也看不清楚。","Wǒ líbùkāi yǎnjìng, méiyǒu yǎnjìng, wǒ yígè zì yě kànbùqīngchǔ.","Anh không thể thiếu kính, không có kính anh chẳng nhìn rõ chữ nào."],["周太太","你去房间找找，是不是刚才放在桌子上了？","Nǐ qù fángjiān zhǎo zhǎo, shìbúshì gāngcái fàngzài zhuōzi shàng le?","Anh vào phòng tìm thử xem, có phải lúc nãy để trên bàn không?"],["周明","我怎么看得到啊？你快过来帮忙啊。","Wǒ zěnme kàn dédào a? nǐ kuài guòlái bāngmáng a.","Anh làm sao mà nhìn thấy được? Em mau qua giúp anh đi."],["周太太","好吧，我帮你去找找。","Hǎo ba, wǒ bāng nǐ qù zhǎo zhǎo.","Được rồi, em giúp anh tìm."]]},{"p":["在打电话","Nói chuyện qua điện thoại"],"l":[["同学","今天的作业你做完了吗？","Jīntiān de zuòyè nǐ zuò wán le ma?","Bài tập hôm nay cậu làm xong chưa?"],["儿子","刚做完，你呢？","Gāng zuò wán, nǐ ne?","Vừa làm xong, còn cậu?"],["同学","今天这些题特别难，我看不懂，不会做，你能帮我吗？","Jīntiān zhèxiē tí tèbié nán, wǒ kànbùdǒng, búhuì zuò, nǐ néng bāng wǒ ma?","Mấy bài hôm nay khó quá, mình đọc không hiểu, không biết làm, cậu giúp mình được không?"],["儿子","电话里讲不明白，你来我家吧，我给你讲讲。","Diànhuà lǐ jiǎng bù míngbái, nǐ lái wǒjiā ba, wǒ gěi nǐ jiǎngjiǎng.","Qua điện thoại giảng không rõ được, cậu đến nhà mình đi, mình giảng cho."],["同学","好啊，我锻炼完了就过去。","Hǎo a, wǒ duànliàn wán le jiù guòqù.","Được, mình tập thể dục xong sẽ qua."]]},{"p":["在休息室","Trong phòng giải lao"],"l":[["同事","你怎么有点儿不高兴？","Nǐ zěnme yǒudiǎnér bù gāoxìng?","Sao anh có vẻ không vui?"],["小刚","我想请小丽吃饭，但是找不到好饭馆儿。","Wǒ xiǎng qǐng xiǎolì chīfàn, dànshì zhǎo búdào hǎo fànguǎnér.","Tôi muốn mời Tiểu Lệ ăn cơm nhưng không tìm được quán ăn nào ngon."],["同事","那你请她听音乐会吧，她喜欢听音乐。","Nà nǐ qǐng tā tīng yīnyuèhuì ba, tā xǐhuān tīng yīnyuè.","Thế anh mời cô ấy đi nghe hòa nhạc đi, cô ấy thích nghe nhạc."],["小刚","音乐会人太多，买不到票。","Yīnyuèhuì réntàiduō, mǎibúdào piào.","Buổi hòa nhạc đông người quá, không mua được vé."],["同事","那去公园走走，聊聊天儿吧。","Nàqù gōngyuán zǒuzǒu, liáoliáotiān ér ba.","Vậy ra công viên đi dạo, trò chuyện đi."],["小刚","公园太大，多累啊。","Gōngyuán tài dà, duōlèi a.","Công viên rộng quá, mệt lắm."]]},{"p":["在客厅","Trong phòng khách"],"l":[["周太太","你怎么还喝咖啡？","Nǐ zěnme hái hēkāfēi?","Sao anh còn uống cà phê?"],["周明","怎么了？","Zěnme le?","Sao thế?"],["周太太","你不是说晚上睡不着觉吗？","Nǐ búshì shuō wǎnshàng shuìbùzhe jué ma?","Chẳng phải anh nói buổi tối không ngủ được sao?"],["周明","没事，我只喝一杯。","Méishì, wǒ zhǐ hēyībēi.","Không sao, anh chỉ uống một cốc."],["周太太","你还是喝杯牛奶吧，可以睡得更好些。","Nǐ háishì hēbēi niúnǎi ba, kěyǐ shuìdé gènghǎo xiē.","Anh vẫn nên uống cốc sữa đi, có thể ngủ ngon hơn."],["周明","好吧，牛奶呢？","Hǎo ba, niúnǎi ne?","Được thôi, sữa đâu?"],["周太太","还没买呢。","Hái méi mǎi ne.","Vẫn chưa mua."]]}]},{"n":7,"t":["我跟她都认识五年了。","Wǒ gēn tā dōu rènshí wǔnián le.","Tôi và cô ấy quen nhau năm năm rồi."],"s":[{"p":["在办公室","Trong văn phòng"],"l":[["同事","那个漂亮的新同事是谁？","Nàge piàoliàng de xīn tóngshì shì shuí?","Cô đồng nghiệp mới xinh đẹp kia là ai vậy?"],["小刚","那是小丽。","Nà shì xiǎolì.","Đó là Tiểu Lệ."],["同事","她刚来北京吗？","Tā gānglái běijīng ma?","Cô ấy mới đến Bắc Kinh à?"],["小刚","不，她在北京工作三年了。","Bù, tā zài běijīng gōngzuò sānnián le.","Không, cô ấy làm việc ở Bắc Kinh ba năm rồi."],["同事","以前她在哪儿工作？","Yǐqián tā zài nǎér gōngzuò?","Trước đây cô ấy làm ở đâu?"],["小刚","她在银行工作了两年以后来的我们公司。","Tā zài yínháng gōngzuò le liǎngnián yǐhòu lái de wǒmen gōngsī.","Cô ấy làm ở ngân hàng hai năm rồi mới đến công ty chúng ta."]]},{"p":["在休息室","Trong phòng giải lao"],"l":[["同事","周末你跟小丽去哪儿玩儿了？","Zhōumò nǐ gēn xiǎolìqù nǎér wánér le?","Cuối tuần anh với Tiểu Lệ đi đâu chơi?"],["小刚","我们去唱歌了。","Wǒmen qù chànggē le.","Chúng tôi đi hát."],["同事","你们唱了多久？","Nǐmen chàng le duōjiǔ?","Các anh hát bao lâu?"],["小刚","我们唱了两个小时歌，晚上还去听音乐会了。","Wǒmen chàng le liǎnggè xiǎoshí gē, wǎnshàng hái qù tīng yīnyuèhuì le.","Chúng tôi hát hai tiếng, buổi tối còn đi nghe hòa nhạc nữa."],["同事","你们都对音乐感兴趣吗？","Nǐmen dōu duì yīnyuè gǎnxìngqù ma?","Các anh đều thích âm nhạc à?"],["小刚","她对音乐感兴趣，我对她更感兴趣。","Tā duì yīnyuè gǎnxìngqù, wǒ duì tā gèng gǎnxìngqù.","Cô ấy thích âm nhạc, còn tôi thích cô ấy hơn."]]},{"p":["在休息室","Trong phòng giải lao"],"l":[["小刚","我跟小丽下个月结婚，到时候欢迎你来。","Wǒ gēn xiǎolì xiàgèyuè jiéhūn, dàoshíhòu huānyíng nǐ lái.","Tháng sau tôi và Tiểu Lệ kết hôn, đến lúc đó mời anh đến dự."],["同事","什么？结婚？","Shénme? jiéhūn?","Cái gì? Kết hôn?"],["小刚","对啊，突然吗？","Duì a, tūrán ma?","Đúng vậy, đột ngột lắm à?"],["同事","你们不是刚认识吗？","Nǐmen búshì gāng rènshí ma?","Hai người chẳng phải mới quen nhau sao?"],["小刚","我跟她都认识五年了。","Wǒ gēn tā dōu rènshí wǔnián le.","Tôi và cô ấy quen nhau năm năm rồi."],["同事","你跟她结婚，那我怎么办啊？","Nǐ gēn tā jiéhūn, nà wǒ zěnmebàn a?","Anh cưới cô ấy, vậy tôi biết làm sao đây?"]]},{"p":["在公司门口","Ở trước cửa công ty"],"l":[["小丽","你看看手表，怎么迟到了？","Nǐ kànkàn shǒubiǎo, zěnme chídào le?","Anh xem đồng hồ đi, sao lại đến muộn?"],["小刚","没迟到啊。","Méi chídào a.","Đâu có muộn."],["小丽","你不是说七点半来接我吗？你迟到了一刻钟。","Nǐ búshì shuō qīdiǎn bànlái jiē wǒ ma? nǐ chídào le yīkèzhōng.","Chẳng phải anh nói bảy rưỡi đến đón em sao? Anh muộn mười lăm phút rồi."],["小刚","现在不是七点半吗？","Xiànzài búshì qīdiǎn bàn ma?","Bây giờ chẳng phải bảy rưỡi sao?"],["小丽","已经差一刻八点了！我都在这儿坐了半个小时了。","Yǐjīng chà yīkè bādiǎn le! wǒ dōu zài zhèér zuò le bàngè xiǎoshí le.","Đã tám giờ kém mười lăm rồi! Em ngồi đây nửa tiếng rồi."],["小刚","不是我迟到了，是你的表快了一刻钟。","Búshì wǒ chídào le, shì nǐ de biǎokuài le yīkèzhōng.","Không phải anh đến muộn, mà là đồng hồ của em chạy nhanh mười lăm phút."]]}]},{"n":8,"t":["你去哪儿我就去哪儿。","Nǐ qù nǎér wǒ jiù qù nǎér.","Em đi đâu thì anh đi đó."],"s":[{"p":["在休息室","Trong phòng giải lao"],"l":[["同事","听说你最近打算买房子？","Tīngshuō nǐ zuìjìn dǎsuàn mǎifángzi?","Nghe nói dạo này cô định mua nhà à?"],["小丽","是，昨天去看了看，今天又去看了看，明天还要再去看看。","Shì, zuótiān qù kàn le kàn, jīntiān yòu qù kàn le kàn, míngtiān háiyào zài qù kànkàn.","Đúng vậy, hôm qua đi xem rồi, hôm nay lại đi xem, ngày mai còn phải đi xem nữa."],["同事","都不满意吗？","Dōu bù mǎnyì ma?","Đều không vừa ý à?"],["小丽","一个没有电梯，不方便。一个有电梯，但是在二十层。","Yígè méiyǒu diàntī, bù fāngbiàn. yígè yǒu diàntī, dànshì zài èrshí céng.","Một chỗ không có thang máy, không tiện. Một chỗ có thang máy nhưng ở tầng hai mươi."],["同事","二十层怎么了？","Èrshí céng zěnme le?","Tầng hai mươi thì sao?"],["小丽","太高了，往下看多害怕啊！","Tàigāo le, wǎngxià kàn duō hàipà a!","Cao quá, nhìn xuống sợ lắm!"]]},{"p":["在学校","Ở trường"],"l":[["小明","听说你下个星期就要回国了？","Tīngshuō nǐ xiàgèxīngqī jiùyào huíguó le?","Nghe nói tuần sau cậu về nước rồi à?"],["马可","是啊，真不想离开北京。","Shì a, zhēn bùxiǎng líkāi běijīng.","Đúng vậy, thật không muốn rời Bắc Kinh chút nào."],["小明","我下星期不在北京，不能去机场送你了。","Wǒ xiàxīngqī bù zài běijīng, bùnéng qù jīchǎng sòng nǐ le.","Tuần sau mình không ở Bắc Kinh, không thể ra sân bay tiễn cậu được."],["马可","没关系，你忙吧。","Méiguānxì, nǐ máng ba.","Không sao, cậu cứ bận việc đi."],["小明","这个小熊猫送给你，欢迎你以后再到中国来。","Zhège xiǎoxióngmāo sònggěi nǐ, huānyíng nǐ yǐhòu zài dào zhōngguó lái.","Tặng cậu chú gấu trúc nhỏ này, chào đón cậu sau này lại đến Trung Quốc."],["马可","谢谢。希望以后能再见面。","Xièxiè. xīwàng yǐhòu néng zàijiànmiàn.","Cảm ơn. Hy vọng sau này còn gặp lại nhau."]]},{"p":["在咖啡厅","Ở quán cà phê"],"l":[["小丽","小刚，我们坐哪儿？","Xiǎogāng, wǒmen zuò nǎér?","Tiểu Cương, chúng ta ngồi đâu?"],["小刚","你坐哪儿我就坐哪儿。","Nǐ zuò nǎér wǒ jiù zuò nǎér.","Em ngồi đâu anh ngồi đó."],["小丽","坐这儿吧，这儿安静。你想喝什么饮料？","Zuò zhèér ba, zhèér ānjìng. nǐ xiǎng hē shénme yǐnliào?","Ngồi đây đi, chỗ này yên tĩnh. Anh muốn uống gì?"],["小刚","你喝什么我就喝什么。","Nǐ hē shénme wǒ jiù hē shénme.","Em uống gì anh uống nấy."],["小丽","喝可乐吧。你等我一会儿，我马上回来。","Hē kělèba. nǐ děng wǒ yīhuìer, wǒ mǎshàng huílái.","Uống coca nhé. Anh đợi em một lát, em quay lại ngay."],["小刚","小丽，你去哪儿？你去哪儿我就去哪儿。","Xiǎolì, nǐ qù nǎér? nǐ qù nǎér wǒ jiù qù nǎér.","Tiểu Lệ, em đi đâu? Em đi đâu thì anh đi đó."],["小丽","我去洗手间。","Wǒ qù xǐshǒujiān.","Em đi nhà vệ sinh."]]},{"p":["在周明家","Tại nhà Châu Minh"],"l":[["老同学","快五年了，你几乎没变化。","Kuài wǔnián le, nǐ jīhū méi biànhuà.","Gần năm năm rồi, cậu hầu như không thay đổi gì."],["周太太","谁说的？我胖了，以前的衣服都不能穿了。","Shuí shuō de? wǒ pàng le, yǐqián de yīfú dōu bùnéng chuān le.","Ai nói thế? Mình béo rồi, quần áo trước đây đều không mặc được nữa."],["老同学","健康最重要，胖瘦没关系。","Jiànkāng zuì zhòngyào, pàngshòu méiguānxì.","Sức khỏe là quan trọng nhất, béo gầy không sao cả."],["周太太","是呀，想吃什么就吃什么。","Shì ya, xiǎng chī shénme jiù chī shénme.","Đúng thế, muốn ăn gì thì ăn nấy."],["老同学","你做饭还是周明做饭？","Nǐ zuòfàn háishì zhōumíng zuòfàn?","Cậu nấu cơm hay Châu Minh nấu?"],["周太太","我做，我想吃什么就做什么，想吃多少就做多少。","Wǒ zuò, wǒ xiǎng chī shénme jiù zuò shénme, xiǎng chī duōshǎo jiù zuò duōshǎo.","Mình nấu, mình muốn ăn gì thì nấu nấy, muốn ăn bao nhiêu thì nấu bấy nhiêu."]]}]},{"n":9,"t":["她的汉语说得跟中国人一样好。","Tā de hànyǔ shuō dé gēn zhōngguó rén yīyàng hǎo.","Cô ấy nói tiếng Trung hay như người Trung Quốc vậy."],"s":[{"p":["在教室","Trong lớp học"],"l":[["大山","马可，你的中文越说越好了！","Mǎkě, nǐ de zhōngwén yuè shuō yuè hǎo le!","Marco, tiếng Trung của cậu càng nói càng hay đấy!"],["马可","哪里哪里，我们班李静说得更好。","Nǎlǐ nǎlǐ, wǒmen bān lǐjìng shuō dé gènghǎo.","Đâu có đâu có, Lý Tịnh lớp mình nói còn hay hơn."],["大山","怎么好？","Zěnme hǎo?","Hay thế nào?"],["马可","她的汉语说得跟中国人一样好。","Tā de hànyǔ shuō dé gēn zhōngguó rén yīyàng hǎo.","Cô ấy nói tiếng Trung hay như người Trung Quốc vậy."],["大山","李静？我怎么没听说过这个名字？","Lǐjìng? wǒ zěnme méitīngshuōguò zhège míngzì?","Lý Tịnh? Sao mình chưa từng nghe cái tên này nhỉ?"],["马可","她是我们的汉语老师。","Tā shì wǒmen de hànyǔ lǎoshī.","Cô ấy là giáo viên tiếng Trung của bọn mình."]]},{"p":["在蛋糕店","Ở cửa hàng bánh kem"],"l":[["小丽","别吃了，你已经吃了三块蛋糕了。","Bié chī le, nǐ yǐjīng chī le sānkuài dàngāo le.","Đừng ăn nữa, anh đã ăn ba miếng bánh kem rồi."],["小刚","这是最后一块。","Zhèshì zuìhòu yīkuài.","Đây là miếng cuối cùng."],["小丽","你总是吃甜的东西，会越吃越胖。","Nǐ zǒngshì chī tián de dōngxī, huìyuè chī yuè pàng.","Anh cứ ăn đồ ngọt suốt, sẽ càng ăn càng béo đấy."],["小刚","你放心，我一定不会变胖。","Nǐ fàngxīn, wǒ yídìng búhuì biànpàng.","Em yên tâm, anh nhất định sẽ không béo lên đâu."],["小丽","为什么？","Wèishénme?","Tại sao?"],["小刚","我们家的人都很瘦，吃不胖。","Wǒmen jiā de rén dōu hěnshòu, chībùpàng.","Người nhà anh ai cũng gầy, ăn không béo được."]]},{"p":["在山上","Ở trên núi"],"l":[["小丽","我有点儿害怕。","Wǒ yǒudiǎnér hàipà.","Em hơi sợ."],["小刚","怎么了？","Zěnme le?","Sao thế?"],["小丽","山越高，路越难走。我也越爬越冷。","Shānyuè gāo, lùyuè nán zǒu. wǒ yě yuè páyuè lěng.","Núi càng cao, đường càng khó đi. Em cũng càng leo càng lạnh."],["小刚","不用担心，有我呢，我对这儿比较了解。","Bùyòng dānxīn, yǒu wǒ ne, wǒ duì zhèér bǐjiào liǎojiě.","Đừng lo, có anh đây, anh khá thông thuộc chỗ này."],["小丽","那我们先休息一下，一会儿再爬。","Nà wǒmen xiān xiūxī yīxià, yīhuìer zài pá.","Vậy chúng ta nghỉ một chút trước đã, lát nữa leo tiếp."],["小刚","好，一会儿我们可以从中间这条路上去。","Hǎo, yīhuìer wǒmen kěyǐ cóng zhōngjiān zhè tiáo lùshàng qù.","Được, lát nữa chúng ta có thể đi lên theo con đường ở giữa này."]]},{"p":["在小明家","Tại nhà bạn Minh"],"l":[["同学","小明，你的眼睛怎么跟大熊猫一样了？","Xiǎomíng, nǐ de yǎnjīng zěnme gēn dàxióngmāo yīyàng le?","Tiểu Minh, sao mắt cậu giống gấu trúc thế?"],["小明","我这几天脚疼，没休息好。","Wǒ zhè jǐtiān jiǎoténg, méi xiūxī hǎo.","Mấy hôm nay mình đau chân, nghỉ ngơi không tốt."],["同学","去医院了吗？医生说什么？","Qù yīyuàn le ma? yīshēng shuō shénme?","Đi bệnh viện chưa? Bác sĩ nói gì?"],["小明","他让我多休息。休息得越多，好得越快。","Tā ràng wǒ duō xiūxī. xiūxī dé yuè duō, hǎo dé yuè kuài.","Bác sĩ bảo mình nghỉ ngơi nhiều. Nghỉ càng nhiều, khỏi càng nhanh."],["同学","下个月的篮球比赛，你能参加吗？","Xiàgèyuè de lánqiúbǐsài, nǐ néng cānjiā ma?","Trận bóng rổ tháng sau cậu tham gia được không?"],["小明","一定能参加，一点儿影响也没有。","Yídìng néng cānjiā, yìdiǎnér yǐngxiǎng yě méiyǒu.","Nhất định tham gia được, chẳng ảnh hưởng chút nào."]]}]},{"n":10,"t":["数学比历史难多了。","Shùxué bǐ lìshǐ nánduō le.","Môn Toán khó hơn môn Lịch Sử nhiều."],"s":[{"p":["在教室","Trong lớp học"],"l":[["朋友","大山，你和马可谁个子高？","Dàshān, nǐ hé mǎ kě shuí gèzi gāo?","Đại Sơn, cậu với Marco ai cao hơn?"],["大山","马可比我高，我比马可矮一点儿。","Mǎ kěbǐ wǒ gāo, wǒ bǐmǎ kě ǎi yìdiǎnér.","Marco cao hơn mình, mình thấp hơn Marco một chút."],["朋友","那你们谁大？","Nà nǐmen shuí dà?","Thế ai lớn tuổi hơn?"],["大山","我比马可大两岁。","Wǒ bǐmǎ kědà liǎngsuì.","Mình lớn hơn Marco hai tuổi."],["朋友","你们谁的汉语说得更好？","Nǐmen shuí de hànyǔ shuō dé gènghǎo?","Ai nói tiếng Trung giỏi hơn?"],["大山","马可比我说得好一些，我的汉语没有他好。","Mǎ kěbǐ wǒ shuōdéhǎo yīxiē, wǒ de hànyǔ méiyǒu tā hǎo.","Marco nói giỏi hơn mình một chút, tiếng Trung của mình không bằng cậu ấy."]]},{"p":["在教室","Trong lớp học"],"l":[["小明","我喜欢历史课、体育课，不喜欢数学课。","Wǒ xǐhuān lìshǐkè, tǐyùkè, bù xǐhuān shùxuékè.","Mình thích môn Lịch sử, Thể dục, không thích môn Toán."],["同学","为什么？数学也很有意思啊。","Wèishénme? shùxué yě hěn yǒuyìsi a.","Tại sao? Toán cũng rất thú vị mà."],["小明","我觉得数学比历史难多了，我听不懂。","Wǒ juéde shùxué bǐ lìshǐ nánduō le, wǒ tīngbùdǒng.","Mình thấy Toán khó hơn Lịch sử nhiều, mình nghe không hiểu."],["同学","别担心，我可以帮你。","Bié dānxīn, wǒ kěyǐ bāng nǐ.","Đừng lo, mình có thể giúp cậu."],["小明","好啊，我们每天学多长时间？","Hǎo a, wǒmen měitiān xué duōzhǎngshíjiān?","Được, mỗi ngày chúng ta học bao lâu?"],["同学","一两个小时吧。","Yīliǎnggè xiǎoshí ba.","Khoảng một hai tiếng."]]},{"p":["在休息室","Trong phòng giải lao"],"l":[["同事","你最近比以前来得早多了，搬家了？","Nǐ zuìjìn bǐ yǐqián láidezǎo duō le, bānjiā le?","Dạo này cô đến sớm hơn trước nhiều, chuyển nhà rồi à?"],["小丽","是啊，你不知道？我上个月就搬家了，走路二十分钟就到。","Shì a, nǐ bù zhīdào? wǒ shànggèyuè jiù bānjiā le, zǒulù èrshífēnzhōng jiù dào.","Đúng vậy, anh không biết à? Tháng trước tôi đã chuyển nhà rồi, đi bộ hai mươi phút là đến."],["同事","那很方便啊。","Nà hěn fāngbiàn a.","Thế thì tiện quá."],["小丽","我还打算买辆自行车，骑车七八分钟就能到。","Wǒ hái dǎsuàn mǎiliàng zìxíngchē, qíchē qībāfēnzhōng jiù néng dào.","Tôi còn định mua một chiếc xe đạp, đạp xe bảy tám phút là đến."],["同事","你不是有一辆吗？","Nǐ búshì yǒu yīliàng ma?","Chẳng phải cô có một chiếc rồi sao?"],["小丽","那辆太旧了，要换一辆，很便宜，两三百块钱。","Nàliàng tàijiù le, yàohuàn yīliàng, hěn piányi, liǎngsānbǎi kuàiqián.","Chiếc đó cũ quá rồi, phải đổi chiếc khác, rẻ lắm, hai ba trăm đồng."]]},{"p":["在看房子","Đang xem nhà"],"l":[["大山","这两个地方的房子一样吗？","Zhè liǎnggè dìfāng de fángzi yīyàng ma?","Nhà ở hai chỗ này có giống nhau không?"],["中介","不一样。您看，学校外边的房子比学校里边的大一些。","Bù yīyàng. nín kàn, xuéxiào wàibiān de fángzi bǐ xuéxiào lǐbiān de dà yīxiē.","Không giống. Anh xem, nhà bên ngoài trường to hơn nhà bên trong trường một chút."],["大山","大小没关系，主要是环境，哪个更安静？","Dàxiǎo méiguānxì, zhǔyào shì huánjìng, nǎge gèng ānjìng?","To nhỏ không quan trọng, chủ yếu là môi trường, chỗ nào yên tĩnh hơn?"],["中介","学校里边的没有学校外边的那么安静。","Xuéxiào lǐbiān de méiyǒu xuéxiào wàibiān de nàme ānjìng.","Nhà trong trường không yên tĩnh bằng nhà ngoài trường."],["大山","哪个方便一些呢？","Nǎge fāngbiàn yīxiē ne?","Chỗ nào tiện hơn?"],["中介","学校里边比学校外边方便，附近有三四个车站。","Xuéxiào lǐbiān bǐ xuéxiào wàibiān fāngbiàn, fùjìn yǒu sānsìgè chēzhàn.","Trong trường tiện hơn ngoài trường, gần đó có ba bốn bến xe."]]}]},{"n":11,"t":["别忘了把空调关了。","Biéwàngle bǎ kōngtiáo guān le.","Đừng quên tắt máy điều hòa nhé."],"s":[{"p":["在教室","Trong lớp học"],"l":[["小明","我先走了。","Wǒ xiān zǒu le.","Mình đi trước nhé."],["同学","你去哪儿？","Nǐ qù nǎér?","Cậu đi đâu?"],["小明","我去图书馆借本书。","Wǒ qù túshūguǎn jiè běnshū.","Mình đến thư viện mượn sách."],["同学","帮我把这本词典还了吧。","Bāng wǒ bǎ zhè běncídiǎn hái le ba.","Trả giúp mình cuốn từ điển này nhé."],["小明","好，等一会儿你离开教室的时候，记得把灯关了。","Hǎo, děng yīhuìer nǐ líkāi jiàoshì de shíhòu, jìde bǎ dēngguān le.","Được, lát nữa lúc cậu rời lớp nhớ tắt đèn nhé."],["同学","好的，放心吧。","Hǎo de, fàngxīn ba.","Được, yên tâm đi."]]},{"p":["在会议室","Trong phòng họp"],"l":[["周明","会议结束后，别忘记把空调关了。","Huìyì jiéshù hòu, biéwàngjì bǎ kōngtiáo guān le.","Họp xong đừng quên tắt điều hòa nhé."],["小丽","好的。王经理两点左右来了个电话。","Hǎo de. wángjīnglǐ liǎngdiǎn zuǒyòu lái le gè diànhuà.","Vâng. Khoảng hai giờ giám đốc Vương có gọi điện đến."],["周明","他已经到北京了？","Tā yǐjīng dào běijīng le?","Anh ấy đến Bắc Kinh rồi à?"],["小丽","是的，他正坐地铁来我们公司呢。","Shì de, tā zhèng zuòdìtiě lái wǒmen gōngsī ne.","Vâng, anh ấy đang đi tàu điện ngầm đến công ty chúng ta."],["周明","等他到了就告诉我。","Děng tā dào le jiù gàosù wǒ.","Đợi anh ấy đến thì báo tôi nhé."]]},{"p":["在客厅","Trong phòng khách"],"l":[["妈妈","还差一双筷子，你去拿一下。","Hái chà yīshuāng kuàizi, nǐ qù ná yīxià.","Còn thiếu một đôi đũa, con đi lấy đi."],["儿子","今天怎么做了这么多菜？","Jīntiān zěnme zuò le zhème duōcài?","Hôm nay sao nấu nhiều món thế ạ?"],["妈妈","今天是你爸爸的生日。","Jīntiān shì nǐ bàbà de shēngrì.","Hôm nay là sinh nhật bố con."],["儿子","真的啊？我把爸爸的生日忘了。那我们今天喝点儿啤酒吧。","Zhēnde a? wǒ bǎ bàbà de shēngrì wàng le. nà wǒmen jīntiān hē diǎnér píjiǔ ba.","Thật ạ? Con quên mất sinh nhật bố. Vậy hôm nay chúng ta uống chút bia nhé."],["妈妈","医生说你爸爸一口酒都不能喝，别让他看见酒瓶子。","Yīshēng shuō nǐ bàbà yīkǒu jiǔdōu bùnéng hē, bié ràng tā kànjiàn jiǔpíngzi.","Bác sĩ nói bố con một ngụm rượu cũng không được uống, đừng để bố nhìn thấy chai rượu."]]},{"p":["短文","Đoạn văn"],"l":[["叙","这个笔记本电脑我去年买的时候要五千块左右，现在便宜多了。我想把这个电脑卖了，再买一个更好的。现在我每天起床后的第一件事就是打开电脑，看电子邮件。我已经很少写信，也很少用笔写字，已经习惯用电脑来学习和工作了。哪一天突然没有了电脑，我们怎么办呢？","Zhège bǐjìběndiànnǎo wǒ qùnián mǎi de shíhòu yào wǔqiānkuài zuǒyòu, xiànzài piányi duō le. wǒ xiǎng bǎ zhège diànnǎo mài le, zài mǎi yígè gènghǎo de. xiànzài wǒ měitiān qǐchuáng hòu de dìyījiàn shì jiùshì dǎkāi diànnǎo, kàn diànziyóujiàn. wǒ yǐjīng hěnshǎo xiěxìn, yě hěnshǎo yòngbǐ xiězì, yǐjīng xíguàn yòng diànnǎo lái xuéxí hé gōngzuò le. nǎyītiān tūrán méiyǒu le diànnǎo, wǒmen zěnmebàn ne?","Chiếc máy tính xách tay này lúc tôi mua năm ngoái khoảng năm nghìn đồng, bây giờ rẻ hơn nhiều rồi. Tôi muốn bán chiếc máy này rồi mua một chiếc tốt hơn. Bây giờ việc đầu tiên mỗi ngày sau khi thức dậy của tôi là mở máy tính xem email. Tôi đã rất ít viết thư, cũng rất ít dùng bút viết chữ, đã quen dùng máy tính để học tập và làm việc. Nếu một ngày nào đó bỗng nhiên không có máy tính, chúng ta sẽ làm thế nào?"]]}]},{"n":12,"t":["把重要的东西放在我这儿吧。","Bǎ zhòngyào de dōngxī fàngzài wǒ zhèér ba.","Hãy để những đồ quan trọng ở chỗ tôi đi."],"s":[{"p":["在家","Ở nhà"],"l":[["小丽","今天太阳从西边出来了吗？","Jīntiān tàiyáng cóng xībiān chūlái le ma?","Hôm nay mặt trời mọc ở đằng tây à?"],["小刚","怎么了？","Zěnme le?","Sao thế?"],["小丽","你怎么这么早就要睡觉了？以前都要12点以后才睡觉。","Nǐ zěnme zhème zǎojiù yào shuìjiào le? yǐqián dōu yào 12 diǎn yǐhòu cái shuìjiào.","Sao anh đi ngủ sớm thế? Trước đây phải sau 12 giờ mới ngủ."],["小刚","我明天8点就要到公司。","Wǒ míngtiān 8 diǎn jiùyào dào gōngsī.","Ngày mai 8 giờ anh phải có mặt ở công ty."],["小丽","有事吗？","Yǒushìma?","Có việc gì à?"],["小刚","经理生气了，他告诉我，明天8点不到，以后就别来了。","Jīnglǐ shēngqì le, tā gàosù wǒ, míngtiān 8 diǎn búdào, yǐhòu jiù biélái le.","Giám đốc giận rồi, ông ấy bảo anh, ngày mai 8 giờ không đến thì sau này đừng đến nữa."]]},{"p":["在家","Ở nhà"],"l":[["小刚","我要跟周经理去外地办事，明天的飞机。","Wǒyào gēn zhōu jīnglǐ qù wàidì bànshì, míngtiān de fēijī.","Anh phải đi công tác tỉnh ngoài với giám đốc Châu, máy bay ngày mai."],["小丽","那我帮你把衣服放到行李箱里吧。什么时候回来？","Nà wǒ bāng nǐ bǎ yīfú fàngdào xínglǐxiāng lǐ ba. shénme shíhòu huílái?","Vậy em giúp anh xếp quần áo vào vali nhé. Khi nào anh về?"],["小刚","一个星期就回来。","Yígè xīngqī jiù huílái.","Một tuần là về."],["小丽","啊？一个星期以后才回来？","A? yígè xīngqī yǐhòu cái huílái?","Hả? Một tuần sau mới về à?"],["小刚","你要自己照顾好自己，我已经给你准备好吃的和喝的了。","Nǐ yào zìjǐ zhàogù hǎo zìjǐ, wǒ yǐjīng gěi nǐ zhǔnbèi hǎochī de hé hē de le.","Em phải tự chăm sóc bản thân nhé, anh đã chuẩn bị đồ ăn thức uống cho em rồi."],["小丽","好吧。我已经把我的照片放在你的包里了。","Hǎo ba. wǒ yǐjīng bǎ wǒ de zhàopiān fàngzài nǐ de bāolǐ le.","Được rồi. Em đã để ảnh của em vào túi anh rồi."]]},{"p":["在机场","Ở sân bay"],"l":[["周明","你怎么才来？","Nǐ zěnme cái lái?","Sao bây giờ cậu mới đến?"],["小刚","对不起，周经理，来机场的路上我才发现忘带护照了。","Duìbùqǐ, zhōu jīnglǐ, lái jīchǎng de lùshàng wǒ cái fāxiàn wàngdài hùzhào le.","Xin lỗi giám đốc Châu, trên đường đến sân bay tôi mới phát hiện quên mang hộ chiếu."],["周明","快点吧，飞机就要起飞了。","Kuàidiǎn ba, fēijī jiùyào qǐfēi le.","Nhanh lên, máy bay sắp cất cánh rồi."],["小刚","您有钱吗？司机把我送到机场的时候，我才发现忘记带钱包了。","Nín yǒuqián ma? sījī bǎ wǒ sòngdào jīchǎng de shíhòu, wǒ cái fāxiàn wàngjì dài qiánbāo le.","Ông có tiền không? Lúc tài xế đưa tôi đến sân bay tôi mới phát hiện quên mang ví."],["周明","我看你还是把重要的东西放在我这儿吧。","Wǒ kàn nǐ háishì bǎ zhòngyào de dōngxī fàngzài wǒ zhèér ba.","Tôi thấy cậu vẫn nên để những đồ quan trọng ở chỗ tôi đi."]]},{"p":["短文","Đoạn văn"],"l":[["叙","我是一个中学老师，教学生画画儿。每次下课前，我都会把下次学生需要带的东西写在黑板上，但是每次上课时，总会有学生忘了拿铅笔，所以我有点儿生气，不是因为他们没带铅笔，是因为他们没有好的学习习惯。","Wǒ shì yígè zhōngxuélǎoshī, jiào xuéshēng huàhuà ér. měicì xiàkè qián, wǒ dōu huì bǎ xiàcì xuéshēng xūyào dài de dōngxī xiě zài hēibǎn shàng, dànshì měicì shàngkèshí, zǒnghuì yǒu xuéshēng wàng le ná qiānbǐ, suǒyǐ wǒ yǒudiǎnér shēngqì, búshì yīnwèi tāmen méidài qiānbǐ, shìyīnwèi tāmen méiyǒu hǎo de xuéxí xíguàn.","Tôi là giáo viên trung học, dạy học sinh vẽ tranh. Mỗi lần trước khi tan học, tôi đều viết lên bảng những thứ học sinh cần mang cho buổi sau, nhưng lần nào lên lớp cũng có học sinh quên mang bút chì. Vì thế tôi hơi giận, không phải vì các em không mang bút chì mà vì các em không có thói quen học tập tốt."]]}]},{"n":13,"t":["我是走回来的。","Wǒ shì zǒu huílái de.","Anh đi bộ về."],"s":[{"p":["在家","Ở nhà"],"l":[["小丽","你终于回来了！从哪儿买回来这么多东西啊？","Nǐ zhōngyú huílái le! cóng nǎér mǎihuílái zhème duō dōngxī a?","Cuối cùng anh cũng về! Anh mua đâu về nhiều đồ thế?"],["小刚","都是从那边的商店买回来的。","Dōu shìcóng nàbiān de shāngdiàn mǎihuílái de.","Đều mua ở cửa hàng bên kia về."],["小丽","怎么还买红酒回来了？谁喝啊？","Zěnme hái mǎi hóngjiǔ huílái le? shuí hē a?","Sao còn mua cả rượu vang về? Ai uống?"],["小刚","这是给爷爷的礼物，明天我们一起送过去，看看爷爷奶奶。","Zhè shì gěi yéyé de lǐwù, míngtiān wǒmen yìqǐ sòng guòqù, kànkàn yéyénǎinǎi.","Đây là quà cho ông, ngày mai chúng ta cùng mang qua, thăm ông bà."],["小丽","那我的礼物呢？快拿出来让我看看。","Nà wǒ de lǐwù ne? kuài ná chūlái ràng wǒ kànkàn.","Thế quà của em đâu? Mau lấy ra cho em xem nào."],["小刚","我不是已经回来了吗？","Wǒ búshì yǐjīng huílái le ma?","Chẳng phải anh đã về rồi sao?"]]},{"p":["在家","Ở nhà"],"l":[["小丽","我今天看见你和一个女的进了咖啡店，她是谁啊？","Wǒ jīntiān kànjiàn nǐ hé yígè nǚ de jìn le kāfēidiàn, tā shì shuí a?","Hôm nay em thấy anh cùng một cô gái vào quán cà phê, cô ấy là ai vậy?"],["小刚","她是我今天在路上遇到的一个老同学。","Tā shì wǒ jīntiān zài lùshàng yùdào de yígè lǎotóngxué.","Cô ấy là bạn học cũ anh tình cờ gặp trên đường hôm nay."],["小丽","你们就一起去喝咖啡了？","Nǐmen jiù yìqǐ qù hēkāfēi le?","Thế là hai người cùng đi uống cà phê à?"],["小刚","是啊，一边喝咖啡一边说了些过去的事。","Shì a, yībiān hēkāfēi yībiān shuō le xiē guòqù de shì.","Đúng vậy, vừa uống cà phê vừa kể chuyện ngày xưa."],["小丽","你回来得这么晚，是说了很多过去的事吗？","Nǐ huílái dé zhèmewǎn, shì shuō le hěnduō guòqù de shì ma?","Anh về muộn thế này là vì kể nhiều chuyện ngày xưa à?"],["小刚","不是。没有公共汽车了，我是走回来的。","Búshì. méiyǒu gōnggòngqìchē le, wǒ shì zǒu huílái de.","Không phải. Hết xe buýt rồi, anh đi bộ về."]]},{"p":["在打电话","Nói chuyện qua điện thoại"],"l":[["同事","小丽，周末你一般跟小刚出去看电影吗？","Xiǎolì, zhōumò nǐ yìbān gēn xiǎo gāngchūqù kàn diànyǐng ma?","Tiểu Lệ, cuối tuần cô thường đi xem phim với Tiểu Cương à?"],["小丽","我很少去电影院看电影，我更愿意在家看电视。","Wǒ hěnshǎo qù diànyǐngyuàn kàn diànyǐng, wǒ gèng yuànyì zàijiā kàndiànshì.","Tôi rất ít đi rạp xem phim, tôi thích ở nhà xem tivi hơn."],["同事","看电视有什么意思啊？","Kàndiànshì yǒu shénme yìsi a?","Xem tivi thì có gì hay?"],["小丽","可以一边吃一边看，坐久了还可以站起来休息一会儿。","Kěyǐ yībiān chī yībiān kàn, zuòjiǔ le hái kěyǐ zhàn qǐlái xiūxī yīhuìer.","Có thể vừa ăn vừa xem, ngồi lâu rồi còn có thể đứng dậy nghỉ một lát."],["同事","你应该多出去走走，这样你们的生活会更有意思。","Nǐ yīnggāi duō chūqù zǒuzǒu, zhèyàng nǐmen de shēnghuó huì gèng yǒuyìsi.","Cô nên ra ngoài nhiều hơn, như thế cuộc sống của hai người sẽ thú vị hơn."],["小丽","有他在，我的生活已经很有意思了。","Yǒu tā zài, wǒ de shēnghuó yǐjīng hěn yǒuyìsi le.","Có anh ấy ở bên, cuộc sống của tôi đã rất thú vị rồi."]]},{"p":["短文","Đoạn văn"],"l":[["叙","刚结婚的时候，我丈夫是中学老师，他喜欢每天早上起床后，一边吃早饭一边看报纸。十年过去了，现在他已经是校长了，因为太忙，每天早上我起床后都看不到他，晚上很晚他才回到家。我真怕他累坏了。希望他能少一些会议，多一些休息，可以经常和我还有孩子在一起。","Gāng jiéhūn de shíhòu, wǒ zhàngfū shì zhōngxuélǎoshī, tā xǐhuān měitiān zǎoshàng qǐchuáng hòu, yībiān chī zǎofàn yībiān kàn bàozhǐ. shínián guòqù le, xiànzài tā yǐjīng shì xiàozhǎng le, yīnwèi tàimáng, měitiān zǎoshàng wǒ qǐchuáng hòu dōu kànbúdào tā, wǎnshàng hěnwǎn tā cái huídào jiā. wǒ zhēnpà tā lèihuài le. xīwàng tā néng shǎo yīxiē huìyì, duōyīxiē xiūxī, kěyǐ jīngcháng hé wǒ háiyǒu háizi zài yìqǐ.","Lúc mới cưới, chồng tôi là giáo viên trung học, anh ấy thích mỗi sáng thức dậy vừa ăn sáng vừa đọc báo. Mười năm trôi qua, bây giờ anh ấy đã là hiệu trưởng. Vì quá bận nên sáng nào tôi dậy cũng không thấy anh, tối rất muộn anh mới về nhà. Tôi thật sợ anh ấy mệt quá đổ bệnh. Mong anh ấy có thể họp ít hơn, nghỉ ngơi nhiều hơn, có thể thường xuyên ở bên tôi và các con."]]}]},{"n":14,"t":["你把水果拿过来。","Nǐ bǎ shuǐguǒ ná guòlái.","Cậu hãy mang trái cây đến đây."],"s":[{"p":["在家","Ở nhà"],"l":[["周太太","客人就要来了，你怎么还不打扫房间啊？","Kèrén jiùyào lái le, nǐ zěnme hái bù dǎsǎo fángjiān a?","Khách sắp đến rồi, sao anh còn chưa dọn phòng?"],["周明","别着急，我让孩子们打扫呢，客人来的时候，他们会把房间打扫干净。","Biézháojí, wǒ ràng háizi men dǎsǎo ne, kèrén lái de shíhòu, tāmen huì bǎ fángjiān dǎsǎo gānjìng.","Đừng sốt ruột, anh bảo bọn trẻ dọn rồi, lúc khách đến chúng sẽ dọn phòng sạch sẽ."],["周太太","那你也不能看电视啊。","Nà nǐ yě bùnéng kàndiànshì a.","Thế anh cũng không được xem tivi chứ."],["周明","你让我做什么？","Nǐ ràng wǒ zuò shénme?","Em muốn anh làm gì?"],["周太太","先把茶和杯子放好，然后把冰箱里的西瓜拿出来。","Xiān bǎ chá hé bēizi fàng hǎo, ránhòu bǎ bīngxiāng lǐ de xīguā ná chūlái.","Trước hết bày trà và cốc ra, sau đó lấy dưa hấu trong tủ lạnh ra."],["周明","太热了，我还是先把空调打开吧。","Tàirè le, wǒ háishì xiān bǎ kōngtiáo dǎkāi ba.","Nóng quá, anh vẫn nên bật điều hòa trước đã."]]},{"p":["在打电话","Nói chuyện qua điện thoại"],"l":[["同事","你在忙什么呢？刚才打你的手机你也不接。","Nǐ zài máng shénme ne? gāngcái dǎ nǐ de shǒujī nǐ yě bùjiē.","Anh đang bận gì vậy? Vừa rồi gọi di động anh cũng không nghe."],["小刚","对不起，我刚洗了个澡，没听见。有什么事吗？","Duìbùqǐ, wǒgāng xǐ le gè zǎo, méi tīngjiàn. yǒu shénme shì ma?","Xin lỗi, tôi vừa tắm xong, không nghe thấy. Có việc gì không?"],["同事","我想问问你公司里的一些事情。","Wǒ xiǎng wènwèn nǐ gōngsī lǐ de yīxiē shìqíng.","Tôi muốn hỏi anh một số việc ở công ty."],["小刚","你先等一下，我去把电视关了。","Nǐ xiān děng yīxià, wǒ qù bǎ diànshì guān le.","Anh đợi một chút, tôi đi tắt tivi đã."],["同事","没关系，你先把电视节目看完吧，然后再给我回电话。","Méiguānxì, nǐ xiān bǎ diànshìjiémù kàn wán ba, ránhòu zài gěi wǒ huí diànhuà.","Không sao, anh cứ xem hết chương trình tivi đi, sau đó gọi lại cho tôi."]]},{"p":["在小明家","Tại nhà bạn Minh"],"l":[["同学","今晚的月亮真漂亮，像白色的盘子一样。","Jīnwǎn de yuèliàng zhēn piàoliàng, xiàng báisè de pánzi yīyàng.","Trăng tối nay đẹp thật, giống như cái đĩa màu trắng vậy."],["小明","是啊，外边也不刮风，我们坐在外边一边看月亮一边吃东西，怎么样？","Shì a, wàibiān yě bù guāfēng, wǒmen zuòzài wàibiān yībiān kàn yuèliàng yībiān chī dōngxī, zěnmeyàng?","Đúng vậy, bên ngoài cũng không có gió, chúng ta ngồi ngoài vừa ngắm trăng vừa ăn gì đó, được không?"],["同学","好啊，我先把桌椅搬出去，然后你把水果拿过来，我们听叔叔阿姨讲讲他们年轻时候的故事。","Hǎo a, wǒ xiān bǎ zhuōyǐ bānchūqù, ránhòu nǐ bǎ shuǐguǒ ná guòlái, wǒmen tīng shūshū āyí jiǎngjiǎng tāmen niánqīng shíhòu de gùshì.","Được đấy, mình mang bàn ghế ra trước, sau đó cậu mang trái cây đến, chúng ta nghe chú dì kể chuyện hồi trẻ."],["小明","太好了！记得给大山打个电话，让他马上过来。","Tàihǎole! jìde gěi dàshān dǎgè diànhuà, ràng tā mǎshàng guòlái.","Tuyệt quá! Nhớ gọi điện cho Đại Sơn, bảo cậu ấy qua ngay nhé."],["同学","不用打了，你听外边的声音，一定是大山。","Bùyòng dǎ le, nǐ tīng wàibiān de shēngyīn, yídìng shì dàshān.","Không cần gọi đâu, cậu nghe tiếng bên ngoài kìa, chắc chắn là Đại Sơn."]]},{"p":["短文","Đoạn văn"],"l":[["叙","你吃过水果饭吗？你在饭馆儿的菜单上见过水果饭吗？你想学着做水果饭吗？其实做水果饭很简单，先把米饭做好，然后再把一块块新鲜的水果放进去，水果饭就做好了。你可以做苹果饭、香蕉饭，要是你愿意，还可以做西瓜饭。多吃新鲜水果对身体好。","Nǐ chī guò shuǐguǒ fàn ma? nǐ zài fànguǎnér de càidān shàngjiàn guò shuǐguǒ fàn ma? nǐ xiǎngxué zhe zuò shuǐguǒ fàn ma? qíshí zuò shuǐguǒ fàn hěn jiǎndān, xiān bǎ mǐfàn zuòhǎo, ránhòu zài bǎ yīkuàikuài xīnxiān de shuǐguǒ fàngjìnqù, shuǐguǒ fàn jiù zuòhǎo le. nǐ kěyǐ zuò píngguǒ fàn, xiāngjiāo fàn, yàoshì nǐ yuànyì, hái kěyǐ zuò xīguā fàn. duō chī xīnxiān shuǐguǒ duì shēntǐ hǎo.","Bạn đã ăn cơm trái cây chưa? Bạn đã thấy cơm trái cây trong thực đơn nhà hàng chưa? Bạn có muốn học làm cơm trái cây không? Thật ra làm cơm trái cây rất đơn giản, trước tiên nấu cơm chín, sau đó cho từng miếng trái cây tươi vào là xong. Bạn có thể làm cơm táo, cơm chuối, nếu muốn còn có thể làm cơm dưa hấu. Ăn nhiều trái cây tươi tốt cho sức khỏe."]]}]},{"n":15,"t":["其他都没什么问题。","Qítā dōu méishénme wèntí.","Những câu khác đều không có vấn đề gì."],"s":[{"p":["在办公室","Trong văn phòng"],"l":[["大山","老师，我来中国留学两年了，但是我的汉语水平提高得一点儿也不快啊。","Lǎoshī, wǒlái zhōngguó liúxué liǎngnián le, dànshì wǒ de hànyǔ shuǐpíng tígāo dé yìdiǎnér yě bùkuài a.","Thưa cô, em du học ở Trung Quốc hai năm rồi nhưng trình độ tiếng Trung của em tiến bộ chẳng nhanh chút nào."],["老师","你每天认真学习，做练习、完成作业，一直不错啊。","Nǐ měitiān rènzhēnxuéxí, zuò liànxí, wánchéng zuòyè, yìzhí bùcuò a.","Em ngày nào cũng học chăm chỉ, làm bài tập, hoàn thành bài về nhà, vẫn luôn rất tốt mà."],["大山","这是我昨天的作业，您帮我看看对不对。","Zhè shì wǒ zuótiān de zuòyè, nín bāng wǒ kànkàn duì bù duì.","Đây là bài tập hôm qua của em, cô xem giúp em đúng không ạ."],["老师","写得不错，除了这个句子意思有些不清楚外，其他都没什么问题。","Xiědé bùcuò, chúle zhège jùzi yìsi yǒuxiē bù qīngchǔ wài, qítā dōu méishénme wèntí.","Viết tốt đấy, ngoài câu này ý hơi chưa rõ ra, những câu khác đều không có vấn đề gì."],["大山","谢谢老师！","Xièxiè lǎoshī!","Em cảm ơn cô!"],["老师","以后有什么不明白的地方，可以给我打电话或者发电子邮件。","Yǐhòu yǒu shénme bù míngbái de dìfāng, kěyǐ gěi wǒ dǎdiànhuà huòzhě fā diànziyóujiàn.","Sau này có chỗ nào không hiểu, em có thể gọi điện hoặc gửi email cho cô."]]},{"p":["在教室","Trong lớp học"],"l":[["学生","老师，除了小云，其他人都来了。","Lǎoshī, chúle xiǎoyún, qítārén dōu lái le.","Thưa thầy, trừ Tiểu Vân ra, mọi người đều đến rồi."],["老师","比赛马上就要开始了，小云怎么还没来？","Bǐsài mǎshàng jiùyào kāishǐ le, xiǎoyún zěnme hái méilái?","Cuộc thi sắp bắt đầu rồi, sao Tiểu Vân còn chưa đến?"],["学生","刚才给她打电话了，她在路上呢。","Gāngcái gěi tā dǎdiànhuà le, tā zài lùshàng ne.","Vừa rồi em gọi điện cho bạn ấy, bạn ấy đang trên đường."],["老师","不等她了，我先给大家讲讲这次比赛的要求和一些需要注意的地方。","Bù děng tā le, wǒ xiān gěi dàjiā jiǎngjiǎng zhècì bǐsài de yāoqiú hé yīxiē xūyào zhùyì de dìfāng.","Không đợi nữa, thầy nói trước cho cả lớp yêu cầu của cuộc thi lần này và một số điểm cần chú ý."],["学生","老师，您放心，今天的比赛我们一定能拿第一。","Lǎoshī, nín fàngxīn, jīntiān de bǐsài wǒmen yídìng néng ná dìyī.","Thầy yên tâm, cuộc thi hôm nay chúng em nhất định giành giải nhất."]]},{"p":["在休息室","Trong phòng giải lao"],"l":[["同事","现在用电脑上网真方便啊！","Xiànzài yòng diànnǎo shàngwǎng zhēn fāngbiàn a!","Bây giờ dùng máy tính lên mạng tiện thật!"],["小刚","是啊，除了看新闻，人们还可以在网上听歌、看电影、买东西。","Shì a, chúle kàn xīnwén, rénmen hái kěyǐ zài wǎngshàng tīnggē, kàn diànyǐng, mǎi dōngxī.","Đúng vậy, ngoài đọc tin tức, mọi người còn có thể nghe nhạc, xem phim, mua sắm trên mạng."],["同事","对了，你从网上买的那件衣服呢？怎么没见你穿？","Duì le, nǐ cóng wǎngshàng mǎi de nàjiàn yīfú ne? zěnme méijiàn nǐ chuān?","À phải rồi, cái áo anh mua trên mạng đâu? Sao không thấy anh mặc?"],["小刚","那件衣服我穿着有点儿小，给我弟弟了。","Nà jiàn yīfú wǒ chuānzhe yǒudiǎnér xiǎo, gěi wǒ dìdi le.","Cái áo đó tôi mặc hơi chật, cho em trai tôi rồi."],["同事","他满意吗？","Tā mǎnyì ma?","Cậu ấy có hài lòng không?"],["小刚","不用花钱，还有新衣服穿，他满意极了。","Bùyòng huāqián, háiyǒu xīn yīfú chuān, tā mǎnyì jíle.","Không phải tốn tiền mà còn có áo mới mặc, cậu ấy hài lòng lắm."]]},{"p":["短文","Đoạn văn"],"l":[["叙","除了春节、中秋节以外，啤酒节也是这里很重要的一个节日。这个地方每年夏天都要举行一次啤酒节。在啤酒节上，你可以喝到世界上不同地方的啤酒。除了喝啤酒，你还可以在街道两边看到世界上不同地方的歌舞。你想不想了解世界各个地方的啤酒文化？来这里的啤酒节看看吧。","Chúle chūnjié, zhōngqiūjié yǐwài, píjiǔjié yě shì zhèlǐ hěn zhòngyào de yígè jiérì. zhège dìfāng měinián xiàtiān dōu yào jǔxíng yīcì píjiǔjié. zài píjiǔjié shàng, nǐ kěyǐ hē dào shìjiè shàng bùtóng dìfāng de píjiǔ. chúle hēpíjiǔ, nǐ hái kěyǐ zài jiēdào liǎngbiān kàndào shìjiè shàng bùtóng dìfāng de gēwǔ. nǐ xiǎng bùxiǎng liǎojiě shìjiè gègè dìfāng de píjiǔ wénhuà? lái zhèlǐ de píjiǔjié kànkàn ba.","Ngoài Tết Nguyên đán và Tết Trung thu, lễ hội bia cũng là một ngày lễ rất quan trọng ở đây. Mùa hè hàng năm nơi này đều tổ chức một lễ hội bia. Tại lễ hội, bạn có thể uống bia từ nhiều nơi khác nhau trên thế giới. Ngoài uống bia, bạn còn có thể xem ca múa của các nơi trên thế giới ở hai bên đường phố. Bạn có muốn tìm hiểu văn hóa bia của các nơi trên thế giới không? Hãy đến lễ hội bia ở đây xem nhé."]]}]},{"n":16,"t":["我现在累得下了班就想睡觉。","Wǒ xiànzài lèidé xià le bān jiù xiǎng shuìjiào.","Bây giờ tôi mệt đến nỗi tan làm chỉ muốn đi ngủ."],"s":[{"p":["在公司","Trong công ty"],"l":[["小丽","我不喜欢一直住在同一个城市，想去其他城市看一看。","Wǒ bù xǐhuān yìzhí zhù zài tóngyīgè chéngshì, xiǎng qù qítā chéngshì kànyīkàn.","Tôi không thích sống mãi ở một thành phố, muốn đi xem những thành phố khác."],["周明","我年轻的时候也这么想，但是那时候没有钱，如果有钱，就去了。","Wǒ niánqīng de shíhòu yě zhème xiǎng, dànshì nà shíhòu méiyǒu qián, rúguǒ yǒuqián, jiù qù le.","Hồi trẻ tôi cũng nghĩ vậy, nhưng lúc đó không có tiền, nếu có tiền thì đã đi rồi."],["小丽","那您现在为什么不去？","Nà nín xiànzài wèishénme bùqù?","Vậy bây giờ sao ông không đi?"],["周明","现在钱不是问题了，主要是没有时间。","Xiànzài qián búshì wèntí le, zhǔyào shì méiyǒu shíjiān.","Bây giờ tiền không phải vấn đề nữa, chủ yếu là không có thời gian."],["小丽","我认为现在您有时间也不会出去玩儿。","Wǒ rènwéi xiànzài nín yǒu shíjiān yě búhuì chūqù wánér.","Tôi nghĩ bây giờ ông có thời gian cũng sẽ không đi chơi đâu."],["周明","你说得对，我现在累得下了班就想睡觉。","Nǐ shuōdéduì, wǒ xiànzài lèidé xià le bān jiù xiǎng shuìjiào.","Cô nói đúng, bây giờ tôi mệt đến nỗi tan làm chỉ muốn đi ngủ."]]},{"p":["在同事家","Tại nhà đồng nghiệp"],"l":[["同事","谢谢你们来看我女儿。你送的小皮鞋和小帽子真漂亮！","Xièxiènǐmen láikàn wǒ nǚér. nǐ sòng de xiǎo píxié hé xiǎomàozi zhēn piàoliàng!","Cảm ơn các bạn đến thăm con gái tôi. Đôi giày da và chiếc mũ nhỏ bạn tặng đẹp quá!"],["小丽","别客气，你女儿长得白白的、胖胖的，真可爱！现在多高了？","Bié kèqì, nǐ nǚér zhǎngdé báibáide, pàngpàngde, zhēn kěài! xiànzài duōgāo le?","Đừng khách sáo, con gái chị trắng trẻo bụ bẫm, thật đáng yêu! Bây giờ cao bao nhiêu rồi?"],["同事","快1米了，25公斤。","Kuài 1 mǐ le, 25 gōngjīn.","Gần 1 mét rồi, 25 cân."],["小丽","你看她鼻子小小的，头发黑黑的，长得像谁？","Nǐ kàn tā bízi xiǎoxiǎode, tóufà hēihēide, zhǎngdé xiàng shuí?","Chị xem mũi bé xinh, tóc đen nhánh, bé giống ai vậy?"],["同事","像她爸爸，刚出生时她爸爸高兴得一个晚上都没睡着。","Xiàng tā bàbà, gāngchūshēng shí tā bàbà gāoxìng dé yígè wǎnshàng dōu méi shuìzháo.","Giống bố nó, lúc mới sinh bố nó vui đến mức cả đêm không ngủ được."]]},{"p":["在公司","Trong công ty"],"l":[["小刚","我的牙还是很疼。","Wǒ de yá háishì hěn téng.","Răng tôi vẫn còn đau lắm."],["同事","如果不舒服，就去医院检查一下吧。","Rúguǒ bù shūfú, jiù qù yīyuàn jiǎncháyīxià ba.","Nếu khó chịu thì đến bệnh viện khám đi."],["小刚","检查好几次了，但是没什么用。","Jiǎnchá hǎo jǐcì le, dànshì méishénme yòng.","Khám mấy lần rồi nhưng chẳng có tác dụng gì."],["同事","大夫怎么说的？","Dàfū zěnme shuō de?","Bác sĩ nói thế nào?"],["小刚","每次医生都告诉我，回家好好儿刷牙。","Měicì yīshēng dōu gàosù wǒ, huíjiā hǎohǎoér shuāyá.","Lần nào bác sĩ cũng bảo tôi về nhà đánh răng cho cẩn thận."]]},{"p":["短文","Đoạn văn"],"l":[["叙","很多人都觉得现在人和人的关系冷冷的，这可能是因为工作太忙，忙得没时间跟别人见面，累得不愿意和别人多说话。其实，我们应该多对别人笑笑，说话时如果能多用一些“您好”“谢谢”这样的词语，和别人的关系就会变得更好。","Hěnduō rén dōu juéde xiànzài rén hé rén de guānxì lěnglěngde, zhè kěnéng shìyīnwèi gōngzuò tàimáng, máng dé méi shíjiān gēn biérén jiànmiàn, lèidé bù yuànyì hé biérén duō shuōhuà. qíshí, wǒmen yīnggāi duō duì biérén xiàoxiào, shuōhuà shí rúguǒ néng duōyòng yīxiē \" nínhǎo \" \" xièxiè \" zhèyàng de cíyǔ, hé biérén de guānxì jiù huì biàndé gènghǎo.","Nhiều người cảm thấy bây giờ quan hệ giữa người với người lạnh nhạt, có lẽ vì công việc quá bận, bận đến mức không có thời gian gặp người khác, mệt đến mức không muốn nói chuyện nhiều với ai. Thật ra chúng ta nên cười với người khác nhiều hơn, khi nói chuyện nếu dùng nhiều những từ như \"xin chào\", \"cảm ơn\", quan hệ với người khác sẽ tốt đẹp hơn."]]}]},{"n":17,"t":["谁都有办法看好你的“病”。","Shuí dōu yǒu bànfǎ kànhǎo nǐ de \" bìng \".","Ai cũng có cách chữa khỏi \"bệnh\" của em."],"s":[{"p":["在公司","Trong công ty"],"l":[["小丽","周经理，下个星期我可以请几天假吗？","Zhōu jīnglǐ, xiàgèxīngqī wǒ kěyǐ qǐng jǐtiān jiǎ ma?","Giám đốc Châu, tuần sau tôi có thể xin nghỉ mấy ngày không?"],["周明","你有什么事？","Nǐ yǒu shénme shì?","Cô có việc gì?"],["小丽","我的一个老朋友结婚，我跟他两年没见了。","Wǒ de yígè lǎopéngyǒu jiéhūn, wǒ gēn tā liǎngnián méijiàn le.","Một người bạn cũ của tôi kết hôn, tôi với anh ấy hai năm không gặp rồi."],["周明","你一共想请几天假？","Nǐ yīgòng xiǎng qǐng jǐtiān jiǎ?","Cô muốn xin nghỉ tổng cộng mấy ngày?"],["小丽","三天。","Sāntiān.","Ba ngày."]]},{"p":["在公司","Trong công ty"],"l":[["同事","小丽，那个高高的男人是你们公司的吗？你对他了解吗？","Xiǎolì, nàge gāogāode nánrén shì nǐmen gōngsī de ma? nǐ duì tā liǎojiě ma?","Tiểu Lệ, người đàn ông cao cao kia là người công ty cô à? Cô có hiểu về anh ấy không?"],["小丽","我们过去是邻居，后来是大学同学，关系一直很不错。","Wǒmen guòqù shì línjū, hòulái shì dàxué tóngxué, guānxì yìzhí hěn bùcuò.","Trước đây chúng tôi là hàng xóm, sau đó là bạn đại học, quan hệ luôn rất tốt."],["同事","他一般喜欢做什么？","Tā yìbān xǐhuān zuò shénme?","Anh ấy thường thích làm gì?"],["小丽","他有很多爱好，唱歌、画画儿、踢足球，什么都会。","Tā yǒu hěnduō àihào, chànggē, huàhuà ér, tīzúqiú, shénme dōu huì.","Anh ấy có nhiều sở thích, hát, vẽ, đá bóng, cái gì cũng biết."],["同事","真的？那你介绍我们认识认识吧。","Zhēnde? nà nǐ jièshào wǒmen rènshí rènshí ba.","Thật à? Vậy cô giới thiệu chúng tôi làm quen đi."],["小丽","不行，现在他是我丈夫。","Bùxíng, xiànzài tā shì wǒ zhàngfū.","Không được, bây giờ anh ấy là chồng tôi."]]},{"p":["在家","Ở nhà"],"l":[["周太太","最近我觉得哪儿都不舒服，你带我去医院检查检查吧。","Zuìjìn wǒ juéde nǎér dōu bù shūfú, nǐ dàiwǒqù yīyuàn jiǎnchá jiǎnchá ba.","Dạo này em thấy chỗ nào cũng khó chịu, anh đưa em đi bệnh viện khám đi."],["周明","不用去医院，谁都有办法看好你的“病”。我问你，你多久没运动了？","Bùyòng qù yīyuàn, shuí dōu yǒu bànfǎ kànhǎo nǐ de \" bìng \". wǒ wèn nǐ, nǐ duōjiǔ méi yùndòng le?","Không cần đi bệnh viện, ai cũng có cách chữa khỏi \"bệnh\" của em. Anh hỏi em, em bao lâu rồi không vận động?"],["周太太","我三年没运动了。","Wǒ sānnián méi yùndòng le.","Em ba năm không vận động rồi."],["周明","谁都知道运动对身体好。但是你吃饱了就睡。","Shuí dōu zhīdào yùndòng duì shēntǐ hǎo. dànshì nǐ chībǎo le jiù shuì.","Ai cũng biết vận động tốt cho sức khỏe. Nhưng em ăn no xong là ngủ."],["周太太","为了健康，我真应该多锻炼锻炼了。从明天起，我决定每天去长跑。","Wèile jiànkāng, wǒ zhēn yīnggāi duō duànliàn duànliàn le. cóng míngtiān qǐ, wǒ juédìng měitiān qù chángpǎo.","Vì sức khỏe, em thật sự nên tập luyện nhiều hơn. Từ mai em quyết định ngày nào cũng chạy bộ đường dài."]]},{"p":["短文","Đoạn văn"],"l":[["叙","“运动很重要”这句话谁都懂。但是你知道怎么运动吗？第一，要选择“对”的时间。一般来说，早上9点是最好的时间，冬天要再晚一些。第二，要选择“对”的地点，公园、山上、游泳馆，这些地方都可以运动。第三，必须要根据自己的健康情况运动。如果你很久没爬山或者游泳了，运动一会儿就一定要休息休息。还要记得刚运动完口渴的时候，不要马上喝水。","\" yùndòng hěn zhòngyào \" zhèjù huà shuí dōu dǒng. dànshì nǐ zhīdào zěnme yùndòng ma? dìyī, yào xuǎnzé \" duì \" de shíjiān. yìbānláishuō, zǎoshàng 9 diǎn shì zuìhǎo de shíjiān, dōngtiān yào zài wǎn yīxiē. dìèr, yào xuǎnzé \" duì \" de dìdiǎn, gōngyuán, shānshàng, yóuyǒngguǎn, zhèxiē dìfāng dōu kěyǐ yùndòng. dìsān, bìxū yào gēnjù zìjǐ de jiànkāng qíngkuàng yùndòng. rúguǒ nǐ hěnjiǔméi páshān huòzhě yóuyǒng le, yùndòng yīhuìer jiù yídìng yào xiūxī xiūxī. háiyào jìde gāng yùndòng wán kǒukě de shíhòu, búyào mǎshàng hēshuǐ.","Câu \"vận động rất quan trọng\" ai cũng hiểu. Nhưng bạn có biết vận động thế nào không? Thứ nhất, phải chọn thời gian \"đúng\". Nói chung 9 giờ sáng là tốt nhất, mùa đông thì muộn hơn một chút. Thứ hai, phải chọn địa điểm \"đúng\", công viên, trên núi, bể bơi đều có thể vận động. Thứ ba, phải vận động dựa theo tình trạng sức khỏe của mình. Nếu đã lâu không leo núi hay bơi, vận động một lát nhất định phải nghỉ ngơi. Còn phải nhớ lúc vừa vận động xong khát nước thì đừng uống nước ngay."]]}]},{"n":19,"t":["你没看出来吗？","Nǐ méi kàn chūlái ma?","Anh không nhìn ra được à?"],"s":[{"p":["在家","Ở nhà"],"l":[["爸爸","女儿最近喜欢把头发放在耳朵后面，你知道为什么吗？","Nǚér zuìjìn xǐhuān bǎ tóufà fàngzài ěrduǒ hòumiàn, nǐ zhīdào wèishénme ma?","Dạo này con gái thích vén tóc ra sau tai, em có biết vì sao không?"],["妈妈","这样可以使她的脸看上去漂亮一些。","Zhèyàng kěyǐ shǐ tā de liǎn kànshàngqù piàoliàng yīxiē.","Như vậy có thể làm khuôn mặt nó trông xinh hơn."],["爸爸","我最近觉得她和以前不太一样了。","Wǒ zuìjìn juéde tā hé yǐqián bùtài yīyàng le.","Dạo này anh thấy nó không giống như trước nữa."],["妈妈","女儿变化不小，她小时候喜欢短头发，像男孩子一样。","Nǚér biànhuà bùxiǎo, tā xiǎoshíhòu xǐhuān duǎn tóufà, xiàng nánháizi yīyàng.","Con gái thay đổi nhiều đấy, hồi nhỏ nó thích tóc ngắn, giống như con trai."],["爸爸","我也想起来了。她现在慢慢地开始像个女孩子了。","Wǒ yě xiǎng qǐlái le. tā xiànzài mànmàn dì kāishǐ xiàng gè nǚháizi le.","Anh cũng nhớ ra rồi. Bây giờ nó dần dần bắt đầu giống con gái rồi."]]},{"p":["在看照片","Đang xem ảnh"],"l":[["小丽","上次我们参加骑马比赛的照片，我选了几张洗出来了。","Shàngcì wǒmen cānjiā qímǎ bǐsài de zhàopiān, wǒxuǎn le jǐzhāng xǐchūlái le.","Ảnh lần trước chúng ta tham gia thi cưỡi ngựa, tôi chọn mấy tấm rửa ra rồi."],["同事","快给我看看。骑得最快的这位是谁？","Kuàigěiwǒ kànkàn. qídé zuìkuài de zhèwèi shì shuí?","Mau cho tôi xem. Người cưỡi nhanh nhất này là ai?"],["小丽","你没看出来吗？他是小刚啊。","Nǐ méi kàn chūlái ma? tā shì xiǎogāng a.","Anh không nhìn ra à? Đó là Tiểu Cương mà."],["同事","怎么看上去跟现在不太一样？","Zěnme kànshàngqù gēn xiànzài bùtài yīyàng?","Sao trông không giống bây giờ lắm?"],["小丽","他上班穿西服、衬衫，比赛的时候穿的是运动服。","Tā shàngbān chuān xīfú, chènshān, bǐsài de shíhòu chuān de shì yùndòngfú.","Đi làm anh ấy mặc vest, sơ mi, lúc thi đấu thì mặc đồ thể thao."],["同事","他今天穿蓝西服，看上去像40多岁，还是穿运动服让他更年轻。","Tā jīntiān chuān lán xīfú, kànshàngqù xiàng 40 duōsuì, háishì chuān yùndòngfú ràng tā gèng niánqīng.","Hôm nay anh ấy mặc vest xanh, trông như hơn 40 tuổi, vẫn là mặc đồ thể thao trông trẻ hơn."]]},{"p":["在小丽家","Tại nhà chị Lệ"],"l":[["朋友","我们一年没见面了吧？","Wǒmen yīnián méi jiànmiàn le ba?","Chúng ta một năm không gặp rồi nhỉ?"],["小丽","听说你都有女儿了？她多大了？","Tīngshuō nǐ dōu yǒu nǚér le? tā duō dà le?","Nghe nói chị có con gái rồi à? Bé bao nhiêu tuổi rồi?"],["朋友","她去年秋天出生的，刚过完一岁生日。","Tā qùnián qiūtiān chūshēng de, gāngguò wán yīsuì shēngrì.","Bé sinh mùa thu năm ngoái, vừa qua sinh nhật một tuổi."],["小丽","她喜欢什么？我送给她。","Tā xǐhuān shénme? wǒ sònggěi tā.","Bé thích gì? Em tặng bé."],["朋友","她就喜欢听她爸爸学鸟叫。哭的时候，只要她爸爸学小鸟叫，她马上就安静下来了。","Tā jiù xǐhuān tīng tā bàbà xué niǎojiào. kū de shíhòu, zhǐyào tā bàbà xué xiǎoniǎo jiào, tā mǎshàng jiù ānjìngxiàlái le.","Bé chỉ thích nghe bố bắt chước tiếng chim hót. Lúc khóc, chỉ cần bố bắt chước tiếng chim là bé im ngay."],["小丽","啊？这个礼物我没办法送。","A? zhège lǐwù wǒ méi bànfǎ sòng.","Hả? Món quà này em không có cách nào tặng được."]]},{"p":["短文","Đoạn văn"],"l":[["叙","这次旅游，我去了不少地方，每个地方都让我非常难忘。我先去看了黄河，黄河是中国有名的大河，我坐在船上，一边看一边照相。一路上经过了很多地方，每个地方都不一样。我想快点儿把照片发给大家，叫朋友们也高兴高兴。","Zhècì lǚyóu, wǒ qù le bùshǎo dìfāng, měigè dìfāng dōu ràng wǒ fēicháng nánwàng. wǒ xiān qù kàn le huánghé, huánghé shì zhōngguó yǒumíng de dàhé, wǒ zuòzài chuánshàng, yībiān kàn yībiān zhàoxiàng. yīlùshàng jīngguò le hěnduō dìfāng, měigè dìfāng dōu bù yīyàng. wǒ xiǎng kuàidiǎnér bǎ zhàopiān fāgěi dàjiā, jiào péngyǒu men yě gāoxìng gāoxìng.","Chuyến du lịch lần này, tôi đã đi không ít nơi, nơi nào cũng khiến tôi khó quên. Đầu tiên tôi đi xem sông Hoàng Hà, Hoàng Hà là con sông lớn nổi tiếng của Trung Quốc, tôi ngồi trên thuyền vừa ngắm vừa chụp ảnh. Dọc đường đi qua rất nhiều nơi, mỗi nơi một khác. Tôi muốn nhanh chóng gửi ảnh cho mọi người, để bạn bè cũng vui lây."]]}]},{"n":20,"t":["我被他影响了。","Wǒ bèi tā yǐngxiǎng le.","Mình chịu ảnh hưởng từ anh ấy."],"s":[{"p":["在休息室","Trong phòng giải lao"],"l":[["小丽","我的照相机被谁拿走了？怎么找不到了？","Wǒ de zhàoxiàngjī bèi shuí názǒu le? zěnme zhǎo búdào le?","Máy ảnh của tôi bị ai lấy đi rồi? Sao tìm không thấy?"],["同事","你再找找。是不是没带来？","Nǐ zài zhǎo zhǎo. shìbúshì méi dàilái?","Cô tìm lại xem. Có phải không mang đến không?"],["小丽","我找了，没找到啊。","Wǒ zhǎo le, méi zhǎodào a.","Tôi tìm rồi, không thấy."],["同事","别难过，再买一个吧，公司东门外不就有一个大商场吗？","Biénánguò, zài mǎi yígè ba, gōngsī dōngménwài bù jiù yǒu yígè dà shāngchǎng ma?","Đừng buồn, mua cái khác đi, ngoài cổng đông công ty chẳng phải có một trung tâm thương mại lớn sao?"],["小丽","但是我这个月信用卡里的钱已经花得差不多了。","Dànshì wǒ zhège yuè xìnyòngkǎ lǐ de qián yǐjīng huādé chàbuduō le.","Nhưng tiền trong thẻ tín dụng tháng này của tôi đã tiêu gần hết rồi."]]},{"p":["在教室","Trong lớp học"],"l":[["小明","你怎么突然关心起体育来了？","Nǐ zěnme tūrán guānxīn qǐ tǐyù lái le?","Sao cậu bỗng dưng quan tâm đến thể thao vậy?"],["朋友","我的男朋友喜欢看足球比赛，我被他影响的。","Wǒ de nánpéngyǒu xǐhuān kàn zúqiúbǐsài, wǒ bèi tā yǐngxiǎng de.","Bạn trai mình thích xem bóng đá, mình bị anh ấy ảnh hưởng."],["小明","看来只有爱，才能让人有变化。","Kànlái zhǐyǒu ài, cáinéng ràng rén yǒu biànhuà.","Xem ra chỉ có tình yêu mới khiến con người thay đổi."],["朋友","是啊，为了和他的爱好一样，我天天看球赛。","Shì a, wèile hé tā de àihào yīyàng, wǒ tiāntiān kànqiúsài.","Đúng vậy, để có cùng sở thích với anh ấy, ngày nào mình cũng xem bóng đá."],["小明","除了足球，他还影响你什么了？","Chúle zúqiú, tā hái yǐngxiǎng nǐ shénme le?","Ngoài bóng đá, anh ấy còn ảnh hưởng gì đến cậu nữa?"],["朋友","我最近天天上网玩儿游戏，我的成绩差极了。","Wǒ zuìjìn tiāntiān shàngwǎng wánér yóuxì, wǒ de chéngjì chà jíle.","Dạo này ngày nào mình cũng lên mạng chơi game, thành tích của mình kém lắm."]]},{"p":["在饭馆儿","Ở quán ăn"],"l":[["朋友","那个拿着碗吃饭的人是你哥哥吗？他和你长得真像。","Nàge ná zhe wǎn chīfàn de rén shì nǐ gēgē ma? tā hé nǐ zhǎngdé zhēnxiàng.","Người cầm bát ăn cơm kia là anh trai cậu à? Anh ấy giống cậu thật."],["大卫","我们经常被别人认错。","Wǒmen jīngcháng bèi biérén rèncuò.","Chúng mình thường bị người khác nhận nhầm."],["朋友","只有你们的爸爸妈妈才能分出来哪个是哥哥、哪个是弟弟吧。","Zhǐyǒu nǐmen de bàbàmāmā cáinéng fēn chūlái nǎge shì gēgē, nǎge shì dìdi ba.","Chắc chỉ có bố mẹ cậu mới phân biệt được ai là anh ai là em nhỉ."],["大卫","除了父母以外，还有我们自己也能啊。","Chúle fùmǔ yǐwài, háiyǒu wǒmen zìjǐ yě néng a.","Ngoài bố mẹ ra, chúng mình cũng phân biệt được chứ."],["朋友","你们两个除了长得像，还有什么相同的地方？","Nǐmen liǎnggè chúle zhǎngdé xiàng, háiyǒu shénme xiāngtóng de dìfāng?","Hai người ngoài giống nhau về ngoại hình, còn điểm gì giống nhau nữa?"],["大卫","我们住在同一个楼、同一个房间……","Wǒmen zhù zài tóngyīgè lóu, tóngyīgè fángjiān … …","Chúng mình sống cùng một tòa nhà, cùng một phòng…"]]},{"p":["短文","Đoạn văn"],"l":[["叙","年轻人遇到难题，常常很着急，不知道怎么办。其实，不同的问题有不同的解决办法。有些问题看上去很难，但是做起来非常简单，所以得试着做做。有些问题看上去虽然简单，但是解决起来难极了。所以只有真正做事情的时候，才能了解有多难。不过，我们一定要相信：多么难的问题，都会被解决的。","Niánqīngrén yùdào nántí, chángcháng hěnzháojí, bù zhīdào zěnmebàn. qíshí, bùtóng de wèntí yǒu bùtóng de jiějuébànfǎ. yǒuxiē wèntí kànshàngqù hěnnán, dànshì zuò qǐlái fēichángjiǎndān, suǒyǐ déshì zhe zuòzuò. yǒuxiē wèntí kànshàngqù suīrán jiǎndān, dànshì jiějué qǐlái nán jíle. suǒyǐ zhǐyǒu zhēnzhèng zuò shìqíng de shíhòu, cáinéng liǎojiě yǒu duōnán. bùguò, wǒmen yídìng yào xiāngxìn: duōme nán de wèntí, dōu huì bèi jiějué de.","Người trẻ gặp vấn đề khó thường rất sốt ruột, không biết làm sao. Thật ra, vấn đề khác nhau có cách giải quyết khác nhau. Có những vấn đề trông thì khó nhưng làm thì rất đơn giản, vì vậy phải thử làm. Có những vấn đề trông đơn giản nhưng giải quyết thì vô cùng khó. Vì thế chỉ khi thực sự bắt tay vào làm mới biết nó khó đến đâu. Tuy nhiên, chúng ta nhất định phải tin rằng: vấn đề khó đến mấy cũng sẽ được giải quyết."]]}]}]};